Let $u^{*}$ be the true solution to the heat equation defined in (\ref{eq:heat_pde}). Then for any $u\in H^{1}_{t}H^{1}_{x}$, we have
\begin{equation*}
M_{1}(\beta, \epsilon)    ||u - u^{*}||_{H^{1}_{t}H^{1}_{x}}^{2} \leqslant L_{\epsilon,\beta}(u) - L_{\epsilon,\beta}(u^{*}) \leqslant M_{2}(\epsilon,\beta) ||u - u^{*}||_{H^{1}_{t}H^{1}_{x}}^{2},
\end{equation*}
where 
\begin{equation}
M_{1}(\beta,\epsilon):= \frac{1}{3} + \min( \frac{1}{3}, \frac{\beta e^{-\frac{\epsilon}{T}}}{C(d,\epsilon, \Omega)},\frac{\beta e^{-\frac{\epsilon}{T}}}{4} ), \qquad
M_{2}(\beta, \epsilon):= 1+\frac{\beta}{2} + \frac{\beta}{2\epsilon},
\end{equation}
and $C(d,\epsilon, \Omega) > 0$ is a constant depending on $d,\epsilon, $ and $\Omega$.

\label{thm_3.1}
Under Assumptions 1-3 in Appendix~\ref{sec:main_assumptions} and the sampling model~\eqref{regression_model} and~\eqref{regression_model_2}. We have the following bounds on the excess risk.



\label{upper_bound}
\textbf{Case I: supercritical regime $q\leqslant\frac{d}{2}$.} The error is further divided into three sub-regimes:
\begin{equation}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}H^{1}_{x}}^2 \lesssim_{\Omega_T,R}
\begin{cases}
\Bigl(\frac{\log (1+C_{2}N)}{N}\Bigr)^{\frac{4s-2}{4s+2d+2}}, \hspace{1.3cm}\text{if }\, 0\leqslant \lambda \leqslant \frac{e^{T/\epsilon}}{N}\\\\
\Bigl(\frac{\log (1+C_{2}N)e^{T/\epsilon}}{N^{2}\lambda}\Bigr)^{\frac{4s-2}{4s+2d+2}}
, \hspace{0.7cm}\text{ if } \frac{e^{T/\epsilon}}{N}<\lambda\leqslant\lambda^{*}
\\\\ \frac{\lambda}{e^{T/\epsilon}} ,
\,\,\hspace{3.4cm}\text{ if } \lambda^{*}\leqslant\lambda<\infty
\end{cases},
\end{equation}
where \begin{equation}\lambda^{*}:=(\sqrt{\log (1+C_{2}N)}/{N})^{\frac{4s-2}{4s+d}}e^{T/\epsilon}.
\end{equation}

\textbf{Case II: subcritical regime $q>\frac{d}{2}$.} For all $\beta\geqslant0$, we have the following error bound
\begin{equation}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}H^{1}_{x}}^2\lesssim_{\Omega_T,R}
\Bigl(\frac{\log (1+C_{2}N)}{N}\Bigr)^{\frac{4s-2}{4s+d}}.
\end{equation}

\label{minimax_lower_bound}
Fix $\epsilon>0$,\,\,$s\geqslant 1$ and $2p+q=2s+2$ for $0\leqslant p \leqslant s$. Under Assumptions 1-4 in Appendix~\ref{sec:main_assumptions}, we have the following result holds
\begin{equation}
\label{eqn:minimax_lower_bound}
 \inf_{\hat{u}(x,t)}\sup_{u^{*}(f)\in \mathcal{U}} \mathbb{E} \bigg[ ||\hat{u}(x,t) -u^{*}(f)||_{H^{1}_{t}H^{1}_{x}}^{2}\bigg] \gtrsim N^{-{\frac{4s-2}{4s+d}}}.
\end{equation}

\label{thm_3.3}
Suppose the assumptions in Theorem~\ref{thm_3.1} hold. For the empirical minimizer of the total loss function $\hat{u}_J$, we choose $J= J_{1}^{*}$ in \eqref{J_*1} if $p\leqslant \frac{d}{2}$ and $J = J_{2}^{*}$ in \eqref{J_*2} if $q > \frac{d}{2}$. Then the excess risk satisfies the following expectation bound over the training data distribution
\begin{equation}
\mathbb{E}\,\,[\Delta \mathcal{E}_{S}] \lesssim  \frac{e^{T/\epsilon}}{\epsilon}\Bigl(\frac{\sqrt{\log (1+C_{2}N)}}{N}\Bigr)^{\frac{4s-2}{4s+d}},
\end{equation}
where the constant of $\lesssim$ depends only on $\Omega_T$ and $R$.

\label{thm_3.4}
Suppose the assumptions in Theorem~\ref{thm_3.1} hold, the ground truth solution $u^{*}$ to the PDE in (\ref{eq:heat_pde}), and $\hat{u}_{J}$ be empirical minimizer of the total loss function in~\eqref{empirical_loss_function} on the training data. We further assume $q> \frac{d}{2}+1$ and $p\geqslant 2$, then the following result holds 
\begin{align}
\mathbb{E}[\Delta \mathcal{E}_{S,gen}]  \lesssim J^{\frac{d+2} {2}}\cdot \log{J} \cdot \frac{\log(N)}{N},
\end{align}
where the constant of $\lesssim$ depends only on $\epsilon, d, q,R,T, \Omega$, and $F$.

\begin{remark}
\cite{pmlr-v134-lu21a} proved the slow generalization error using a one-layer neural network with $m$ neurons for elliptic PDEs, and \cite{lustatistical} improved this bound to fast generalization error with $J$-truncated Fourier series instead. Their generalization bounds also suffer
from polynomial growth of model parameters in terms of $m$ or $J$. Our Theorem \ref{thm_3.4} achieves the fast rate of generalization error in terms of the effective sample size $n m$. Note that the upper bound on excessive risk in Theorem~\ref{thm_3.3} incorporates approximation error, while Theorem \ref{thm_3.4} only focus on statistical errors. We also impose a slightly stronger assumption $q> \frac{d}{2}+1$ to enforce higher spatial regularity so the Sobolev embedding theorem is applied to enhance local integrability.
\end{remark}

The space 
\begin{equation}
L^{\beta}(0,T;\mathcal{X})
\end{equation}
consists of all measurable functions $f: [0,T] \rightarrow \mathcal{X}$ with \\
\begin{equation}
||f||_{L^{\beta}(0,T;\mathcal{X})} := \begin{cases} \bigg(\displaystyle\int_{0}^{T} ||f(t)||^{\beta}\bigg)^{\frac{1}{\beta}}<\infty, \quad 1\leqslant \beta<\infty,\,\quad\quad \\\\
\underset{0\leqslant t\leqslant T}{ess\,\sup} ||f(t)||<\infty, \quad\quad \beta=\infty
\end{cases} 
\end{equation}

The Sobolev space
\begin{equation}
W^{\alpha,\beta}(0,T;\mathcal{X})
\end{equation}
consists of all functions $f\in L^{\beta}(0,T;\mathcal{X})$ such that weak derivative $\tfrac{\partial^{k} u}{\partial t^{k}}$ exists in the distributional sense and belongs to $L^{\beta}(0,T;\mathcal{X})$. Furthermore, 
\begin{equation}
||u||_{W^{\alpha,\beta}(0,T;\mathcal{X})}:=\begin{cases}
\bigg(\displaystyle\int_{0}^{T} \sum_{k=0}^{\alpha}||\tfrac{\partial^{k}u(t)}{\partial t^{k}}(t,\cdot)||^{\beta}dt\bigg)^{1/\beta},\quad 1\leqslant \beta<\infty\\\\\\
\underset{0\leqslant t\leqslant T}{ess\,\sup} \sum_{k=0}^{\alpha}||\tfrac{\partial^{k}u(t)}{\partial t^{k}}(t,\cdot)||^{\beta}dt, \quad \beta =\infty 
\end{cases}.
\label{time_dependent_sobolev_norm}
\end{equation}
We write $H^{\alpha}(0,T;\mathcal{X}) = W^{\alpha,2}(0,T;\mathcal{X})$. In particular, let $\mathcal{X} = H^{\alpha^{\prime}}(\Omega)$,\,$\alpha^{\prime}>0$, we abbreviate 
\begin{equation}
H^{\alpha}_{t}H^{\alpha^{\prime}}_{x}=H^{\alpha}(0,T;H^{\alpha^{\prime}}(\Omega)).
\end{equation}

\label{Sobolev_extension_theorem}
{\cite[Theorem 5.4, when $\alpha$=1]{evans}\cite[Theorem 1.105]{triebel2006theory}} Let $\Omega\subseteq \mathbb{R}^{d}$ be a bounded Lipschitz domain and the smoothness parameter $\alpha>0$. Then, there exists a linear extension operator 
\begin{equation}
Ext: H^{\alpha}(\Omega) \rightarrow H^{\alpha}(\mathbb{R}^{d})
\end{equation}
such that for any $f\in H^{\alpha}(\Omega)$,
\begin{align}
(i)& Ext\,f \,|_{\Omega} =f ,\,\, \text{a.s} \,\, \text{in} \,\, \Omega, \\
(ii)& ||Ext \,f||_{W^{\alpha,2}(\mathbb{R}^{d})}\leqslant C(\Omega)||f||_{W^{\alpha,2}(\Omega)},
\end{align}
where the constant $C$ depending only on $\Omega$.

\label{space_time_extension}
Let $\Omega \subset \mathbb{R}^d$ be a bounded Lipschitz domain, $T>0$, and smoothness parameters $\alpha_{1},\alpha_{2}\geqslant0$.
There exists a bounded linear operator
\begin{equation}
  Ext : H_t^{\alpha_{2}}\bigl(0,T; H_x^{\alpha_{1}}(\Omega)\bigr)
  \longrightarrow
H_t^{\alpha_{2}}\bigl(\mathbb{R}; H_x^{\alpha_{1}}(\mathbb{R}^d)\bigr)
\end{equation}
such that for every $u \in H_t^1(0,T;H_x^1(\Omega))$:\\\\
$(i)\,\, Ext\, u(t,x) = u(t,x)$ for a.e.\ $(t,x) \in (0,T)\times\Omega$,
\\\\
(ii) There exists a constant $C = C(\Omega,T) > 0$ with
\begin{equation}
    ||Ext \,\,u\|_{H_t^{\alpha_{2}}(\mathbb{R};H_x^{\alpha_{1}}(\mathbb{R}^d))}
    \le C\,\|u\|_{H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\Omega))}.
\end{equation}

We first extend spatial domain $\Omega$ to $\mathbb{R}^{d}$.
Since $\Omega$ is a bounded Lipschitz domain, the
extension Theorem \ref{Sobolev_extension_theorem} provides a bounded linear operator
\begin{equation}
  E_x : H_x^{\alpha_{1}}(\Omega) \longrightarrow H_x^{\alpha_{1}}(\mathbb{R}^d)
\end{equation}
such that for any $t\in[0,T]$, (i) and (ii) of Theorem \ref{Sobolev_extension_theorem} hold for all $u(\cdot,t ) \in H^{\alpha_{1}}(\Omega)$.

For $u \in H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\Omega))$,  we can define
\begin{equation}
  (\hat{E}_x u)(\cdot,t) := E_x\bigl(u(\cdot,t)\bigr),
  \quad \text{for a.e.\ } t \in (0,T).
\end{equation}
Since $E_x$ is bounded operator along with Fubini's theorem, we obtain for every temporal derivative index $\alpha_{2}\geqslant 0$
\begin{equation}
  \int_0^T \|\partial_t^{\alpha_{2}} (\hat{E}_x u)(t)\|_{H^{\alpha_{1}}(\mathbb{R}^d)}^2 \, dt
  \le C_\Omega^2 \int_0^T \|\partial_t^{\alpha_{2}} u(t)\|_{H^{\alpha_{1}}(\Omega)}^2 \, dt.
\end{equation}
This implies $\hat{E}_x u \in H^{\alpha_{2}}(0,T;H^{\alpha_{1}}(\mathbb{R}^d))$. Thus, the operator $ \hat{E}_x : H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\Omega))\to H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\mathbb{R}^d))$ is bounded with

\begin{equation}
  \|\hat{E}_x u\|_{H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\mathbb{R}^d))}
  \le C_\Omega\,\|u\|_{H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\Omega))}.
\end{equation}
Moreover, $(\widetilde E_x u)(t,x) = u(t,x)$, for a.e.\ $(t,x)\in [0,T]\times\Omega$.

Next we apply Sobolev extension theorem again to the interval $(0,T)\subset\mathbb{R}$, with a bounded linear $E_t:\, H^{\alpha_{2}}(0,T) \to H^{\alpha_{2}}(\mathbb{R})$ satisfying (i) and (ii) of Theorem ~\ref{Sobolev_extension_theorem} as well.

Let $X$ be a separable Hilbert space and let
$\{e_k\}_{k\ge 1}$ be an orthonormal basis of $X$.
For $u \in H^{\alpha_{2}}(0,T;X)$, define scalar functions
$u_k(t) := \langle u(t),e_k\rangle_X \in H^{\alpha_{2}}([0,T])$.

Define $\hat{E}_t u : \mathbb{R}\to X$ by
\begin{equation}
  (\hat{E}_t u)(t) := \sum_{k=1}^\infty (E_t u_k)(t) \, e_k,
\end{equation}
and similarly, for every temporal derivative index $\alpha_{2}\geqslant 0$, we obtain
\begin{equation}
  \|\hat{E}_t \partial_{t}^{\alpha_{2}}u\|_{L^2(\mathbb{R};X)}^2
  = \sum_{k=1}^\infty \|E_t \partial_{t}^{\alpha_{2}}u_k\|_{L^2(\mathbb{R})}^2
  \le C_T^2 \sum_{k=1}^\infty \|\partial_{t}^{\alpha_{2}}u_k\|_{L^2(0,T)}^2
  = C_T^2 \|\partial_{t}^{\alpha_{2}}u\|_{L^2(0,T;X)}^2.
\end{equation}
Moreover, for a.e.\ $t\in[0,T]$, we have
\begin{equation}
  (\hat{E}_t u)(t)
  = \sum_{k=1}^\infty (E_t u_k)(t)\,e_k
  = \sum_{k=1}^\infty u_k(t)\,e_k
  = u(t),
\end{equation}

When $X = H_x^1(\mathbb{R}^d)$, $\hat{E}_t : H_t^{\alpha_{2}}\bigl(0,T;H_x^{\alpha_{1}}(\mathbb{R}^d)\bigr)
  \to H_t^{\alpha_{2}}\bigl(\mathbb{R};H_x^{\alpha_{1}}(\mathbb{R}^d)\bigr)$
is bounded and extends functions in time. Finally, we define
\begin{equation}
  Ext := \hat{E}_t \circ \hat{E}_x.
\end{equation}
For $u \in H_t^1(0,T;H_x^1(\Omega))$, we have
\begin{equation}
  Ext\,\, u = \hat{E}_t\bigl(\hat{E}_x u\bigr)
  \in H_t^{\alpha_{2}}\bigl(\mathbb{R};H_x^{\alpha_{1}}(\mathbb{R}^d)\bigr),
\end{equation}
and for a.e.\ $(t,x)\in[0,T]\times\Omega$,
\begin{equation}
  Ext\, u(t,x)
  = \hat{E}_t(\hat{E}_x u)(t,x)
  = (\hat{E}_x u)(t,x)
  = u(t,x),
\end{equation}
so (i) holds. Moreover,
\begin{equation}
  \| Ext \,u\|_{H_t^{\alpha_{2}}(\mathbb{R};H_x^{\alpha_{1}}(\mathbb{R}^d))}
  \le C_T \|\hat{E}_x u\|_{H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\mathbb{R}^d))}
  \le C_T C_\Omega \|u\|_{H_t^{\alpha_{2}}(0,T;H_x^{\alpha_{1}}(\Omega))},
\end{equation}
which yields (ii) with $C(\Omega,T) := C_T\cdot C_\Omega$.

. Assume
\begin{equation}
g\in H^{2m+1}(\Omega), \frac{d^{p}}{dt^{p}}f\in L^{2}(0,T;H^{2m-2p}(\Omega))\quad (p=0,...,m).
\end{equation}
Suppose also that the following $p$-th order compatibility conditions hold: 
\begin{equation}
\begin{cases}
\,\,g_{0}:=g\in H^{1}_{0}(\Omega),\,\, g_{1}:=f(0,x) - Lg_{0} \in H^{1}_{0}(\Omega),\\\\\\
\,\,,....,\,g_{m}:= \displaystyle\frac{d^{p-1}}{dt^{p-1}}f(0,x) - Lg_{p-1} \in H^{1}_{0}(\Omega).
\end{cases}
\label{compatibility_condition}
\end{equation}
Then \begin{equation}
    \frac{d^{p}u}{dt^{p}}\in L^{2}(0,T;H^{2m+2-2p}) \text{ holds for solution } u \text{ to PDEs } (\ref{linear_parabolic_pdes}).
\end{equation}
\label{higher_regulairty_thm}

. Assume $g\in C^{\infty}(\bar{\Omega}), f\in C^{\infty}(\bar{\Omega}_{T})$ and compatibility condition $(\ref{compatibility_condition})$ hold for $m=0,1,2,3,...$\,. Then the parabolic initial/boundary-value problem $(\ref{linear_parabolic_pdes})$ has a unique solution 
\begin{equation}
u\in C^{\infty}(\bar{\Omega}_{T}).
\end{equation}
\label{infinite_regularity_theory}

Let \( \Omega \subseteq \mathbb{R}^n \) be a domain with boundary $\partial \Omega$, and let  $L$ is an elliptic operator defined in (\ref{elliptic_operator})
\label{Duhamel_principle}
\begin{equation}
\begin{cases}
\quad u_t(x,t) - L u(x,t) = f(x,t), & (x,t) \in \Omega \times (0,T],\\
\quad u(x,t) = 0, &(x,t) \in \partial \Omega\times[0,T], \\
\quad u(x,0) = 0, & x \in \Omega.
\end{cases}
\end{equation}
Then the solution to the inhomogeneous problem is given by the Duhamel formula
\begin{equation}
u(x,t) = \int_{0}^{t} (P^s f)(x,\,s)\, \mathrm{d}s = \int_{0}^{t} v(x,\,s)\, \mathrm{d}s.
\end{equation}
where \(P^s\) is the solution operator of the homogeneous problem with $s>0$ 
 \begin{equation}
\begin{cases}
\quad v_t(x,t) - Lv(x,t) = 0, & (x,t)\in \Omega \times (s,T],\\
\quad v(x,t) = 0 , &  (x,t) \in \partial \Omega \times [s,T],\\
\quad v(x,s) = f(x,s), & x\in \Omega.
\end{cases}
\end{equation}

Assume the conditions in Theorem~\ref{Duhamel_principle} holds. Then the solution $u$ to the PDE problem (\ref{linear_parabolic_pdes}) is given by 
\begin{equation}
u(x,t) = g(x) + \int_{0}^{t} w(x,\,s)\, \mathrm{d}s
\end{equation}
where $w(x,t)$ is the solution to homogeneous initial value problem with Dirichlet boundary condition
\begin{equation}
\begin{cases}
\quad w_t(x,t) - Lw(x,t) = 0, & (x,t)\in \Omega \times (0,T],\\
\quad w(x,t) = 0 , &  (x,t) \in \partial \Omega \times [0,T],\\
\quad w(x,0) = g(x).
\end{cases}
\end{equation}

There exists a unique minimizer $u\in \mathcal{U}$ of $I_{\epsilon}(u)$ such that $u$ is a solution to linear hyperbolic PDEs 
\label{euler_lagrangian_for_I}
\begin{equation}\label{euler-lagragian*}
\begin{cases}
&-\epsilon u_{tt} + u_{t} - \triangle u = f,
\quad (x,t) \in \Omega \times (0,T],\\
&u(x,t) = 0,\quad (x,t) \in \partial\Omega \times [0,T],\\
&u(x,0) = u_{0}^{*}(x),\quad x\in \Omega.
\end{cases}
\end{equation}

Recall the definition of the weighted energy functional (WEF) :


\begin{equation}I_{\epsilon}(u) = \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} \left[ \dfrac{1}{2} |u_{t}|^{2} +  \frac{1}{2\epsilon} |\nabla u|^{2} - \frac{1}{\epsilon}f u \right] dx dt.\end{equation}

Note that the Euler-Lagrangian equation depends on the definition of test function. Here we choose test function $v \in C^{\infty}_{c}([0,T]\times\Omega).$ 
For any test function $v \in C^{\infty}_{c}([0,T]\times\Omega),$ we know $
v(\cdot,0) = v(\cdot,T) =0
.$
Then,
\begin{align}
I_{\epsilon}(u+sv) = \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} \dfrac{1}{2} \big|u_{t}+sv_{t}\big|^{2} + \dfrac{1}{2\epsilon} \big| \nabla u+s \nabla v\big|^{2} - \dfrac{1}{\epsilon}f \big(u+sv\big)\hspace{0.5mm}dx dt. \end{align}
We apply Fubini theorem and integration by parts with respect to time $t$:
\begin{align}
\dfrac{d}{ds} I_{\epsilon}(u+sv)\bigg|_{s=0} &= \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega}  u_{t} v_{t} + uv - \dfrac{1}{\epsilon} \triangle uv - \dfrac{1}{\epsilon}fv\hspace{0.5mm}dx dt
\\ &=\int_{0}^{T} e^{-\tfrac{t}{\epsilon}} \int_{\Omega}  \dfrac{1}{\epsilon} u_{t}v  -\dfrac{1}{\epsilon} \triangle uv - \dfrac{1}{\epsilon}fv-  vu_{tt} dxdt\\
&\quad\quad -e^{-\tfrac{T}{\epsilon}} \int_{\Omega}  f(x,T)v(x,T)dx + u_{t}(x,0)v(x,0)dx.
\end{align}
Making appropriate substitutions and matching terms from the above, we obtain\\
\begin{align}
\dfrac{d}{ds} I_{\epsilon}(u+sv)\bigg|_{s=0} &= e^{-\tfrac{T}{\epsilon}} \int_{\Omega} \big( -\triangle u(x,T) + u_{t}(x,T) -f(x,T) \big)v(x,T)dx\\
&\quad\quad+ \int_{0}^{T} \int_{\Omega} e^{-\tfrac{t}{\epsilon}} \big(-u_{tt} + \dfrac{1}{\epsilon} u_{t}  - \dfrac{1}{\epsilon} \triangle u - \dfrac{1}{\epsilon}f\big)vdx dt\\
&\quad\quad+  \int_{\Omega} - u_{t}(x,0) v(x,0)dx\\
&= \int_{0}^{T} \int_{\Omega} e^{-\tfrac{t}{\epsilon}} \big(-u_{tt} + \dfrac{1}{\epsilon} u_{t}  - \dfrac{1}{\epsilon} \triangle u - \dfrac{1}{\epsilon}f\big)vdx dt.
\label{derivative_of_I}
\end{align}
We set $\frac{d}{ds} I_{\epsilon}(u+sv) = 0$ and obtain the corresponding Euler-Lagrangian equations for the functional weighted energy, and the boundary condition is satisfied because $u\in L^{2}_{t}H^{1}_{0,x}$.
\begin{equation}
\begin{cases}
&-\epsilon u_{tt} + u_{t} - \triangle u = f,
\quad (x,t) \in \Omega \times (0,T],\\
&u(x,t) = 0,\quad (x,t) \in \partial\Omega \times [0,T],\\
&u(x,0) = u_{0}^{*}(x), \quad x\in \Omega.
\end{cases}
\end{equation}

Recall that
\begin{equation}
L_{\epsilon,\beta}(u): = 
||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}  + \beta \bigg[I_{\epsilon} (u) + \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}u dx dt - \int_{\Omega} e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)u(x,T) dx\bigg].
\end{equation}
According to the inner product in $H^{1}_{t}(0,T;H^{1}_{x}(\Omega))$, we readily compute first variation of loss function $L_{\epsilon,\beta}(u)$. For any test function $v\in C^{\infty}_{c}(\Omega \times [0,T])$,
\begin{align}
\dfrac{d}{ds} L_{\epsilon,\beta}(u+sv)\bigg|_{s=0} &= 2\langle u -u^{*},v\rangle_{H^{1}_{t}H^{1}_{x}}+ \beta\int_{0}^{T} \int_{\Omega} e^{-\tfrac{t}{\epsilon}} \big(-u_{tt} + \dfrac{1}{\epsilon} u_{t}  - \dfrac{1}{\epsilon} \triangle u - \dfrac{1}{\epsilon}f\big)vdx dt \\
&+\beta \int_{0}^{T} \int_{\Omega} e^{-\tfrac{t}{\epsilon}}u_{tt}^{*}v dxdt-\beta\int_{\Omega} u_{t}(x,0) v(x,0)dx- \beta\int_{\Omega} e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)u(x,T) dx\\
&= 2\langle u -u^{*},v\rangle_{H^{1}_{t}H^{1}_{x}} + \beta\int_{0}^{T} \int_{\Omega} e^{-\tfrac{t}{\epsilon}} \big(u^{*}_{tt}-u_{tt} + \dfrac{1}{\epsilon} u_{t}  - \dfrac{1}{\epsilon} \triangle u - \dfrac{1}{\epsilon}f\big)vdx dt\\
&= 2\int_{0}^{T}\int_{\Omega}(u-u^{*})v dxdt + 2\int_{0}^{T}\int_{\Omega}(\nabla u-
\nabla u^{*}) \nabla v dxdt\\
&\quad\quad + 2\int_{0}^{T}\int_{\Omega}(u_{t} -
u^{*}_{t}) v_{t} dxdt + 2\int_{0}^{T}\int_{\Omega}(\nabla u_{t}-
\nabla u^{*}_{t}) \nabla v_{t}dxdt\\
&\quad\quad + \beta\int_{0}^{T} \int_{\Omega} e^{-\tfrac{t}{\epsilon}} \big(u^{*}_{tt}-u_{tt} + \dfrac{1}{\epsilon} u_{t}  - \dfrac{1}{\epsilon} \triangle u - \dfrac{1}{\epsilon}f\big)vdx dt\\
&= \int_{0}^{T}\int_{\Omega} \bigg[2\bigg(u-u^{*} -\triangle u+ \triangle u^{*} - u_{tt}+u^{*}_{tt}+ \triangle u_{tt} - \triangle u^{*}_{tt}\bigg)\\
&\quad\quad\quad+\frac{\beta}{\epsilon} e^{-\tfrac{t}{\epsilon}}\bigg(\epsilon(u_{tt}^{*}-u_{tt}) +  u_{t} - \triangle u - f\bigg)\bigg]v dxdt.\end{align}
Second equality follows by $v(x,0)=0$ and $v(x,T)=0$; third equality follows by inner product in $H^1_t H^1_x$;last equality follows by integration by parts and vanishing boundary of $v$. Setting $\frac{d}{ds} L_{\epsilon,\beta}(u+sv) = 0$, we obtain 
\begin{equation}
2\bigg[u-u^{*} -\triangle u+ \triangle u^{*} - u_{tt}+u^{*}_{tt}+ \triangle u_{tt} - \triangle u^{*}_{tt}\bigg] +\frac{\beta}{\epsilon} e^{-\tfrac{t}{\epsilon}}\bigg(\epsilon(u_{tt}^{*}-u_{tt}) +  u_{t} - \triangle u - f\bigg) = 0.
\end{equation}

Let $w: = u-u^{*}$, we have $(x,t)$-a.s in $\Omega_{T}$ that
\begin{equation}
2\bigg[w - \triangle w - w_{tt} + \triangle w_{tt}\bigg]+\frac{\beta}{\epsilon} e^{-\tfrac{t}{\epsilon}}(-\epsilon w_{tt} +  w_{t} - \triangle w + u^{*}_{t} - \triangle u^{*}- f) = 0.
\end{equation}\\
Since $u^{*}$ is true solution to heat equation, $u_{t}^{*} - \triangle u^{*} -f=0$, and 
\begin{equation}
\tfrac{\beta}{\epsilon} e^{-\tfrac{t}{\epsilon}}(\epsilon w_{tt} -  w_{t} + \triangle w) = 2\bigg[w - \triangle w - w_{tt} + \triangle u_{tt}\bigg] \,\,,(x,t) \text{-}a.s \text{ in } \Omega_{T}.
\end{equation}
We denote inner product in $L_{2}(\Omega_{T})$
\begin{equation}
\langle u,v\rangle_{L^{2}(\Omega_{T})}: = \int_{0}^{T}\int_{\Omega}uv\,dxdt.
\end{equation}
Taking inner product with respect to $w$ in $L_2(\Omega_{T})$ on both sides and applying integration by parts, we have
\begin{equation}
\langle \tfrac{\beta}{\epsilon} e^{-\tfrac{t}{\epsilon}}(\epsilon w_{tt} -  w_{t} + \triangle w), w\rangle_{L_{2}(\Omega_{T})} = 2\langle w - \triangle w - w_{tt} + \triangle u_{tt}, w\rangle_{L^{2}(\Omega_{T})}.
\end{equation}
Making some rearrangement, we obtain 
\begin{align}
&0\geqslant\bigg[ (2+\beta e^{-\tfrac{T}{\epsilon}})\langle w_{t},w_{t} \rangle_{L_{2}(\Omega_{T})} + (2+\tfrac{\beta}{\epsilon} e^{-\tfrac{T}{\epsilon}}) \langle \nabla w, \nabla w\rangle_{L_{2}(\Omega_{T})}\\
&\quad\quad\quad + 2 \langle w,w \rangle_{L_{2}(\Omega_{T})} + 2\langle \nabla w_{t},\nabla w_{t} \rangle_{L_{2}(\Omega_{T})}\bigg].
\end{align}
Since $\beta$, $\langle w_{t}, w_{t}\rangle_{L_{2}(\Omega_{T})}$, $\langle \nabla w, \nabla w\rangle_{L_{2}(\Omega_{T})}$, $\langle  w,  w\rangle_{L_{2}(\Omega_{T})}$, and $\langle  \nabla w_{t},  \nabla w_{t}\rangle_{L_{2}(\Omega_{T})}$ are nonnegative, we have 
\begin{equation}
w_{t} = 0,\quad \nabla w = 0,\quad \nabla w_{t} = 0, \quad w=0,\quad(x,t)\,a.s \text{ in } \Omega_{T}.
\end{equation}
Since $w = u^{*} - u$, we have
\begin{equation}
u^{*} = u \,\,, (x,t) \text{-}a.s \text{ in } \Omega_{T}.
\end{equation}
Therefore, the minimizer to the total loss function $L_{\epsilon,\beta}(u)$ is the solution to heat equation.

Recall
\begin{equation}
L_{\epsilon,\beta}(u): = 
||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}  + \beta \bigg( I_{\epsilon} (u) +  \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}u dx dt - \int_{\Omega} e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)u(x,T) dxdt\bigg).
\end{equation}
We can write the excess risk as following
\begin{align}
L_{\epsilon,\beta}(u) - L_{\epsilon,\beta}(u^{*}) &= ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}  + \beta \bigg( I_{\epsilon} (u) -  I_{\epsilon} (u^{*})  + \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}(u^{*}-u) dx dt\\
&\quad\quad+ \int_{\Omega} e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)(u^{*}(x,T)-u(x,T)) dxdt \bigg).
\end{align}
\noindent \textbf{Step 1: } Compute $I_{\epsilon}(u) - I_{\epsilon}(u^{*}) + \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}(u^{*}-u) dx dt$.

Recall $f(x,t) = u^{*}_{t}(x,t) - \triangle u^{*}(x,t)$, $(x,t) \in  \Omega_{T}$.  Apply integration by parts, we get
\begin{align}
I_{\epsilon}(u) - I_{\epsilon}(u^{*}) &= \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} \dfrac{1}{2} |u_{t}|^{2} + \dfrac{1}{2\epsilon} |\nabla u|^{2} - \dfrac{1}{\epsilon}f  u dx dt\\
&\quad\quad- \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} \dfrac{1}{2} |u^{*}_{t}|^{2} + \dfrac{1}{2\epsilon} |\nabla u^{*}|^{2} - \dfrac{1}{\epsilon}f  u^{*} dxdt\\
&= \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} \dfrac{1}{2} |u_{t}|^{2} + \dfrac{1}{2\epsilon} |\nabla u|^{2} - \dfrac{1}{\epsilon}(u^{*}_{t}- \triangle u^{*}) u dx dt\\
&\quad\quad+ \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} -\dfrac{1}{2} |u^{*}_{t}|^{2} - \dfrac{1}{2\epsilon} |\nabla u^{*}|^{2} + \dfrac{1}{\epsilon}(u^{*}_{t} - \triangle u^{*}) u^{*} dxdt\\
&= \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} \dfrac{1}{2} |u_{t}|^{2} + \dfrac{1}{2\epsilon} |\nabla u|^{2} - \dfrac{1}{\epsilon}u^{*}_{t} u - \frac{1}{\epsilon}\nabla u^{*}\nabla u dx dt\\
&\quad\quad+ \int_{0}^{T}  e^{-\tfrac{t}{\epsilon}} \int_{\Omega} -\dfrac{1}{2} |u_{t}^{*}|^{2} - \dfrac{1}{2\epsilon} |\nabla u^{*}|^{2} + \dfrac{1}{\epsilon}u^{*}_{t} u^{*} + \frac{1}{\epsilon} |\nabla u^{*}|^{2} dx dt.
\end{align}
By a second integration by parts to $u_{t}^{*}u$ and $|u^{*}_{t}|^2$, we get
\begin{align}
I_{\epsilon}(u) - I_{\epsilon}(u^{*}) &= \int_{0}^{T}\int_{\Omega}e^{-\frac{t}{\epsilon}}\bigg(\frac{1}{2}|u_{t}|^2  - \frac{1}{2}|u_{t}^{*}|^2 +  u_{tt}^{*} (u^{*} -u) +  |u_{t}^{*}|^{2}  - u_{t}^{*}u_{t} \bigg) dxdt\\
&\quad\quad+\int_{\Omega}e^{-\frac{t}{\epsilon}}u^{*}_{t}\bigg(u - u^{*}\bigg)   dx \bigg|_{t=0}^{T}+\int_{0}^{T}\int_{\Omega}\frac{1}{2\epsilon}e^{-\frac{t}{\epsilon}}|\nabla u - \nabla u^{*}|^{2} dx.
\end{align}
By definition of $\mathcal{U}$, $u(x,0) = u^{*}(x,0)$, it follows that
\begin{align}
I_{\epsilon}(u) - I_{\epsilon}(u^{*})&= \int_{0}^{T}\int_{\Omega}e^{-\frac{t}{\epsilon}} u_{tt}^{*} (u^{*}-u) dxdt
 + \int_{\Omega}e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)\big(u(x,T) - u^{*}(x,T)\big)dx \\&\quad\quad+\int_{0}^{T}e^{-\frac{t}{\epsilon}}\int_{\Omega}\frac{1}{2\epsilon}|\nabla u - \nabla u^{*}|^{2} +\frac{1}{2}| u_{t} -u_{t}^{*}|^{2} dxdt.
\end{align}
Then, we obtain 
\begin{align}
I_{\epsilon} (u) - I_{\epsilon} (u^{*})& + \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}(u-u^{*}) dx dt + \int_{\Omega}e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)\big(u^{*}(x,T) - u(x,T)\big)dx\\&=  \int_{0}^{T}\int_{\Omega}\frac{1}{2}e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} dxdt +\int_{0}^{T}\int_{\Omega}\frac{1}{2\epsilon}e^{-\frac{t}{\epsilon}}|\nabla u - \nabla u^{*}|^{2} dx. \label{integrals}
\end{align}
\textbf{Step 2: } Bound $I_{\epsilon} (u) - I_{\epsilon} (u^{*}) + \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}(u^{*}-u) dx dt + \int_{\Omega}e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)\big(u^{*}(x,T) - u(x,T)\big)dx  $ from up and below.

To bound first integral in (\ref{integrals}), we may assume without loss of generality that $u(x,t)-u^{*}(x,t)$ is centered in the following sense
\begin{equation}
\int_{0}^{T} e^{-\frac{t}{\epsilon}}\bigg(u(x,t)- u^{*}(x,t)\bigg)dt = 0.
\end{equation}
According to weighted Poincar\'e inequality in Lemma~\ref{lem:weighted-poincare} with respect to the time variable, there exist constant $C(d,\epsilon, \Omega) > 0$ such that 
\begin{equation}
\frac{1}{C^{2}(d,\epsilon, \Omega)} \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}} |u-u^{*}|^{2}dxdt  \leqslant  \int_{0}^{T}\int_{\Omega}e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} dxdt.
\end{equation}
Then it follows that
\begin{align}
 \int_{0}^{T}\int_{\Omega} \frac{1}{2} e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} &dxdt  =  \int_{0}^{T}\int_{\Omega} \frac{1}{4} e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} dxdt   +  \int_{0}^{T}\int_{\Omega} \frac{1}{4} e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} dxdt  \\
 &\geqslant \frac{1}{C^{2}(d,\epsilon, \Omega)} \int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}} |u-u^{*}|^{2}dxdt +  \int_{0}^{T}\int_{\Omega} \frac{1}{4} e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} dxdt \\
 &=  \min\Bigl\{\frac{e^{-\frac{T}{\epsilon}}}{C^{2}(d,\epsilon, \Omega)},\frac{e^{-\frac{T}{\epsilon}}}{4} \Bigr\} \int_{0}^{T}\int_{\Omega} \Bigl(|u-u^{*}|^2  + |u_{t}-u^{*}_{t}|^2\Bigr) dxdt\\
 &= \min\Bigl\{\frac{e^{-\frac{T}{\epsilon}}}{C^{2}(d,\epsilon, \Omega)},\frac{e^{-\frac{T}{\epsilon}}}{4} \Bigr\} ||u-u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2}.
\end{align}
We obtain
 \begin{equation}
 \int_{0}^{T}\int_{\Omega} \frac{1}{2} e^{-\frac{t}{\epsilon}}| u_{t} -u_{t}^{*}|^{2} dxdt  \leqslant \int_{0}^{T}\int_{\Omega} \frac{1}{2} e^{-\frac{t}{\epsilon}} \Bigl( | u_{t} -u_{t}^{*}|^{2} + |u - u^{*}|^{2} \Bigr)dxdt \leqslant \frac{1}{2}||u-u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2}.
 \label{u_t_bound}
 \end{equation}\\
To bound the second integral in (\ref{integrals})
, we again assume without loss of generality that $u(x,t) - u^{*}(x,t)$ is centered in the following sense
\begin{equation}
\int_{\Omega} u(x,t)- u^{*}(x,t)dx = 0.
\end{equation}
Let's call $P_{\epsilon}(u):= \int_{0}^{T}\int_{\Omega}\frac{1}{2\epsilon}e^{-\frac{t}{\epsilon}} \Bigl(|\nabla u - \nabla u^{*}|^2 + |u - u^{*}|^2 \Bigr) dxdt$.\\

According to standard Poincare inequality to space derivative, we obtain
\begin{align}
\int_{0}^{T}\int_{\Omega}\frac{1}{2\epsilon}e^{-\frac{t}{\epsilon}}|\nabla u - \nabla u^{*}|^{2} dx dt&\leqslant P_{\epsilon}(u)
\leqslant \frac{1}{2\epsilon} ||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2},
\end{align}
and
\begin{align}
\int_{0}^{T}\int_{\Omega}\frac{1}{2\epsilon}e^{-\frac{t}{\epsilon}}|\nabla u - \nabla u^{*}|^{2} &dx dt\geqslant P_{\epsilon}(u)
\geqslant \frac{e^{-\frac{T}{\epsilon}}}{4\epsilon}||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}.
\end{align}
We obtain
\begin{equation}
\frac{e^{-\frac{T}{\epsilon}}}{4\epsilon}||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}\leqslant \int_{0}^{T}\int_{\Omega}\frac{1}{2\epsilon}e^{-\frac{t}{\epsilon}}|\nabla u - \nabla u^{*}|^{2} dx dt \leqslant \frac{1}{2\epsilon} ||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}.
\label{u_grad_bound}
\end{equation}
\textbf{Step 3: }Combine  (\ref{u_t_bound}) and (\ref{u_grad_bound}) together.

Let's denote 
\begin{align}E_{\epsilon, \beta}(u)&: = \beta (I_{\epsilon}(u) - I_{\epsilon}(u^{*})) + \beta\int_{0}^{T}\int_{\Omega} e^{-\frac{t}{\epsilon}}u^{*}_{tt}(u^{*}-u) dx dt\\&  + \int_{\Omega}e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)\big(u^{*}(x,T) - u(x,T)\big)dx .
\end{align}
Then, we have
\begin{align}
 &E_{\epsilon, \beta}(u) \geqslant  \frac{\beta e^{-\frac{T}{\epsilon}}}{4\epsilon}||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} +\min\Bigl\{\frac{\beta e^{-\frac{\epsilon}{T}}}{C^{2}(d,\epsilon, \Omega)},\frac{\beta e^{-\frac{\epsilon}{T}}}{4} \Bigr\} ||u-u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2},\\
&E_{\epsilon, \beta}(u) \leqslant \frac{\beta}{2}||u-u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2}  + \frac{\beta}{2\epsilon}||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}.
\end{align}

\textbf{Step 4:} Embedding into $H^{1}_{t}([0,T];H^{1}_{x}(\Omega))$. 

By the definition of time-dependent Sobolev space (see [\citealp[Chapter 5]{evans}]) and standard $H^1$ embedding into $L^2$, we can absorb lower and upper bound into $||u - u^{*}||_{H^{1}_{t}([0,T];H^{1}_{x}(\Omega))}^{2}$. It is straightforward to establish upper bound
\begin{align}
||u - u^{*}||_{H^{1}_{t}([0,T];H^{1}_{x}(
\Omega))}^{2}+ E_{\epsilon, \beta}(u) \leqslant \Bigl( 1+ \frac{\beta}{2} + \frac{\beta}{2\epsilon} \Bigr) ||u - u^{*}||_{H^{1}_{t}([0,T];H^{1}_{x}(
\Omega))}^{2}.
\end{align}
To obtain lower bound, we have {
\begin{align}
||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}+ E_{\epsilon, \beta}(u) &\geqslant \frac{1}{3} ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} + \frac{1}{3} ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} \\
&+\frac{1}{3} ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}+\frac{\beta e^{-\frac{T}{\epsilon}}}{4\epsilon}||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}\\
&+ \min\Bigl\{\frac{\beta e^{-\frac{\epsilon}{T}}}{C^{2}(d,\epsilon, \Omega)},\frac{\beta e^{-\frac{\epsilon}{T}}}{4} \Bigr\}||u-u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2}\\
&\geqslant \frac{1}{3} ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} + \frac{1}{3} ||\nabla u - \nabla u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2}\\
&+ \min\Bigl\{\frac{\beta e^{-\frac{\epsilon}{T}}}{C^{2}(d,\epsilon, \Omega)},\frac{\beta e^{-\frac{\epsilon}{T}}}{4} \Bigr\}||u-u^{*}||_{H^{1}_{t}(0,T;L^{2}_{x}(\Omega))}^{2}\\
&+\frac{1}{3} ||u_{t} - u^{*}_{t}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} +\frac{\beta e^{-\frac{T}{\epsilon}}}{4\epsilon}||u-u^{*}||_{L^{2}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}
\\& \geqslant ( \frac{1}{3} + \min( \frac{1}{3}, \frac{\beta e^{-\frac{T}{\epsilon}}}{C^{2}(d,\epsilon, \Omega)},\frac{\beta e^{-\frac{T}{\epsilon}}}{4} )) ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} .
\end{align}}
Finally, we obtain 
{
\begin{align}
( \frac{1}{3} + \min( \frac{1}{3}, \frac{\beta e^{-\frac{T}{\epsilon}}}{C^{2}(d,\epsilon, \Omega)},\frac{\beta e^{-\frac{T}{\epsilon}}}{4} )) ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}\leqslant L_{\epsilon,\beta}(u) - L_{\epsilon,\beta}(u^{*})  
\end{align}
and
\begin{align}
 L_{\epsilon,\beta}(u) - L_{\epsilon,\beta}(u^{*})  \leqslant \Bigl( 1+ \frac{\beta}{2} + \frac{\beta}{2\epsilon} \Bigr) ||u - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}.
\end{align}}

\label{high_probability_bound_on_excess_risk}
Under Assumptions A1 - A4 in Appendix \ref{sec:main_assumptions} and define $\mathcal{U}_{J}$ as in (\ref{parametrized_function_class}). For any localization parameter $\rho>0$, define
\begin{equation}
\mathcal{U}_{J}(\rho):=\bigg\{u \in \mathcal{U}_{J} \,\bigg{|} \, S_{*,\epsilon}(u)\leqslant \rho\bigg\}.
\end{equation}\\
Then there exists constant $C_{1}(d,\Omega,T,\epsilon,\beta)$ such that with probability $1-e^{-s}$,\\
\begin{equation}
\underset{u_{J}\in \mathcal{\mathcal{U}_{J}(\rho)}}{\sup}  |\hat{S}_{*,\epsilon}(u_{J}) - S_{*,\epsilon}(u_{J})| \lesssim \psi(\rho,\tau,J) + \sqrt{\frac{2\rho B(\epsilon,\beta,\Omega,T,d)s}{nm}}  + \tau_{1}(\rho, J),
\end{equation}
where

\begin{align}
\psi(\rho,\tau, J)&:=\frac{1}{\sqrt{nm}} J^{\frac{d+2}{2}} \sqrt{\rho B(\epsilon,\beta,\Omega,T,d)\log(1+ \sqrt{\frac{C_{2} \rho} {B(\epsilon,\beta,\Omega,T,d)}}}) + C_{1}(d,\Omega,T, \epsilon, \beta)\sqrt{\frac{\rho }{nm}} 
\end{align}
and
\begin{equation}
\tau_{1}(\rho, J) := \begin{cases} \,\,\frac{J^{d+1}s}{nm} + \frac{RC(\Omega,T)}{nm} J^{2(d+2)}\log(1+ \sqrt{\frac{C_{2} \rho} {B(\epsilon,\beta,\Omega,T,d)}}),\quad q\leqslant\frac{d}{2}, \\\\
\,\,\frac{Rs}{nm}+\frac{RC(\Omega,T)}{nm} J^{d+2}\log(1+ \sqrt{\frac{C_{2} \rho} {B(\epsilon,\beta,\Omega,T,d)}}),\,\,\,\,\quad\quad\, q>\frac{d}{2}.\end{cases}
\end{equation}
$B(\epsilon, \beta, \Omega, T, d): = (\frac{1}{3}+\frac{\beta}{\beta_{0}})^{-1}\,, \beta_{0}:=\frac{1}{C^{2}(d,\epsilon,\Omega)e^{T/\epsilon}}$ and $C(d,\epsilon,\Omega)$\text{ is a Cheeger constant.}

For simplicity of notation, we denote the excess risks as\\
\begin{equation}
S_{*}(u):= L_{\epsilon,\beta}(u) - L_{\epsilon,\beta}(u^{*}),\,\,\hat{S}_{*}(u): = \hat{L}_{\epsilon,\beta}(u) -\hat{L}_{\epsilon,\beta}(u^{*})
\end{equation}
and the space of localized functional class $\mathcal{U}_{J}$ as\\
\begin{equation}
\mathcal{U}_{J}(\rho):= \bigg\{u_{J}\in \mathcal{U}_{J} \,\,\bigg| S_{*,\epsilon}(u_{J})\leqslant \rho   \bigg\}.
\end{equation}

Our goal is to control excess risk $L_{\epsilon,\beta}(\hat{u}_{J}) - L_{\epsilon,\beta}(u^{*})$ for a parametrized estimator $\hat{u}_{J}\in \mathcal{U}_{J}$, where $\mathcal{U}_{J}$ is a class of functions that have Fourier series representations with truncation of the level $J$. First, we decompose the excess risk $L_{\epsilon,\beta}(\hat{u}_{J}) - L_{\epsilon,\beta}(u^{*})$ into telescoping sums, and we view the telescoping sums as a localized version of the empirical process and control empirical process for $u_{J}\in \mathcal{U}_{J}(\rho)$.\\

To start,  we center all functions appropriately and consider the extension of a restriction of the functions $u_{J}$ and $u^{*}$ to compact space $\Omega$ over finite time horizon $[0,T]$ , which
allows us to use Fourier expansions for harmonic analysis. Note that  $u_{J}$ and $u^{*}$ are defined in all of space-time $\mathbb{R}^{d}\times \mathbb{R}$, but we do not need to control their norms over the entire
space-time domain. The existence of such extension is mainly attributed to extension Theorem~\ref{Sobolev_extension_theorem}, which induces space-time expansion Lemma~\ref{space_time_extension}.

With notation of linear extension operator $ext$ defined in Theorem~\ref{space_time_extension}, we use the following notation 
\begin{equation}
ext\, u_{J} = u_{J},\,\, ext\, u^{*} = u^{*}.
\end{equation}

For any $u_{J} \in \mathcal{U}_{J}(p)$, by optimality of $\hat{u}_{J}$ we have
\begin{align}
& L_{\epsilon, \beta}(\hat{u}_{J}) - L_{\epsilon, \beta}(u_{J}) \\
=& L_{\epsilon,\beta}(\hat{u}_{J})- L_{\epsilon,\beta}(u^{*})  +   \hat{L}_{\epsilon,\beta}(u^{*})- \hat{L}_{\epsilon,\beta}(\hat{u}_{J})+\hat{L}_{\epsilon,\beta}(\hat{u}_{J}) -\hat{L}_{\epsilon,\beta}(u^{*}) - L_{\epsilon,\beta}(u_{J}) + L_{\epsilon,\beta}(u^{*})\\
=& L_{\epsilon,\beta}(\hat{u}_{J})- L_{\epsilon,\beta}(u^{*})   -   \hat{L}_{\epsilon,\beta}(\hat{u}_{J})  - \hat{L}_{\epsilon,\beta}(u^{*}) + \hat{L}_{\epsilon,\beta}(\hat{u}_{J}) -\hat{L}_{\epsilon,\beta} (u^{*}) -  L_{\epsilon,\beta}(u_{J}) - L_{\epsilon,\beta}(u^{*})\\
\leqslant& \bigg(S_{*}(\hat{u}_{J}) - \hat{S}_{*} (\hat{u}_{J})\bigg) + \bigg(\hat{S}_{*}(u_{J}) - S_{*}(u_{J})  \bigg).
\end{align}
From the above inequality, it is enough to bound $S_{*}(\hat{u}_{J}) - \hat{S}_{*}(u_{J})$ to control $L_{\epsilon,\beta}(\hat{u}_{J}) - L_{\epsilon,\beta}(u_{J})$. To proceed, we consider bounding a localized version of the above empirical process 
\begin{equation}
 \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup}S_{*}(u_{J}) - \hat{S}_{*} (u_{J}).
\end{equation}
We want to first control the expectation of the supremum. The expectation control has two components: the first component contains the bounding tail error arising from the truncation of the Fourier series at the truncation of level $J$ and the second part contains statistical error from truncated Fourier series itself. Once we obtain upper bound for the expectation, we are able to produce a high-probability bound via Talagrand's concentration inequality, cf. Theorem~\ref{Talagrand Inequality}.
\\\\
For convenience, let's write $h= ext\,(u_{J}- u^{*})$ and its local basis Representation as\\
\begin{align}
h &= \sum_{0\leqslant \tau, |\xi|_{\infty}\leqslant \infty} a_{\tau,\xi} \phi_{\tau,|\xi|_{\infty}}(x,t)\\
&= \sum_{0\leqslant \tau \leqslant J^{2},0\leqslant|\xi|_{\infty} \leqslant J} a_{\tau,\xi} \phi_{\tau,|\xi|_{\infty}}(x,t) + \sum_{\tau>J^{2},|\xi|_{\infty} >J} a_{\tau,\xi} \phi_{\tau,|\xi|_{\infty}}(x,t)\\
&= P_{J,J^{2}}h + P_{>J,>J^{2}}h.
\end{align}
Plugging local basis representation, we obtain 

\begin{align}
& \mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup} |S_{*,\epsilon}(u_{J}) - \hat{S}_{*.\epsilon}(u_{J})| \bigg] \\
=& \mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup} | L_{\epsilon,\beta}(u_{J}) -  \hat{L}_{\epsilon,\beta}(u_{J}) + \hat{L}_{\epsilon,\beta}(u^{*}) - L_{\epsilon,\beta}(u^{*})  | \bigg]\\
=&  \mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup} | (L_{\epsilon,\beta} - \hat{L}_{\epsilon,\beta})(u_{J}-u^{*}) | \bigg] \\
\leqslant&  \underbrace{\mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup} | (L_{\epsilon,\beta} - \hat{L}_{\epsilon,\beta})P_{J, J^{2}}h | \bigg]}_{I_{1}}+ \underbrace{\mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup} | (L_{\epsilon,\beta} - \hat{L}_{\epsilon,\beta})P_{>J,>J^{2}}h | \bigg]}_{I_{2}}.
\end{align}
Here we want to apply Symmetrization technique to $I_{1}$ and $I_{2}$.  Since the sampling scheme \eqref{regression_model} and \eqref{regression_model_2} treats time dimension $t$ as another additional spatial dimension, we flatten $d+1$-d spatial-temporal training data matrix $\{ (x_{ij},t_{j} ) \}_{i=1,j=1}^{n,m}$ to $1$-d data vector $\{z_{i}\}_{i=1}^{nm}$ such that
\[
z_{1} = (x_{11},t_{1}),....,z_{m} = (x_{m1},t_{1}), z_{m+1} =(x_{12},t_{2}),.... ,z_{2m} = (x_{m2},t_{2}),....,z_{mn} = (x_{mn},t_{n}).
\]
In this way, standard symmetrization argument with $nm$ copies of independent Rademacher random variables $\sigma_{i}$ is applied
\begin{equation}
I_{1}\leqslant \underbrace{\frac{1}{nm}\mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup}  \sum_{i=1}^{nm} \sigma_{i}P_{J,J^{2}}h(z_{i})\bigg]}_{T_{1}}, \,\,\,\, I_{2}\leqslant \underbrace{\frac{1}{nm}\mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup}  \sum_{i=1}^{nm} \sigma_{i}P_{>J,>J^{2}}h(z_{i})\bigg]}_{T_{2}}.
\end{equation}
The rest of the subsection is devoted to first bound $T_{2}$ and then bound $T_{1}$.
\vspace{1cm}\\
\textbf{Control of $T_{2}$}:
\begin{equation}
T_{2}: = \frac{1}{nm}\mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup}  \sum_{i=1}^{nm} \sigma_{i}P_{>J,>J^{2}}h(z_{i})\bigg] = \frac{1}{nm}\mathbb{E} \bigg[ \underset{u_{J}\in \mathcal{U}_{J}(\rho)}{\sup}  \sum_{i=1}^{nm} \sigma_{i} \sum_{\tau>J^{2},|\xi|_{\infty} >J} a_{\tau,\xi} \phi_{\tau,\xi}(x,t) \bigg].
\end{equation}
By Cauchy-Schwarz inequality, we obtain
\begin{align}
\sum_{i=1}^{nm} \sigma_{i} \sum_{\tau>J^{2},|\xi|_{\infty} >J} a_{\tau,\xi} \phi_{\tau,\xi}(x,t) \leqslant \underbrace{{\bigg(\sum_{i=1}^{nm} \sigma_{i}^{2}\bigg)^{\frac{1}{2}}}}_{T_{2,1}} \underbrace{\bigg(\sum_{i=1}^{nm} \bigl(\sum_{\tau>J^{2},|\xi|>J}a_{\tau,\xi} \phi_{\tau,\xi}(x,t)\bigr)^{2}\bigg)^{\frac{1}{2}}}_{T_{2,2}}\\
T_{2,2} = \bigg(\sum_{\tau>J^{2},|\xi|_{\infty} >J} a_{\tau,\xi}^{2} \phi_{\tau,\xi}^{2}(z_{i}) + \sum_{1\leqslant j\neq k\leqslant nm } a_{\tau,\xi}^{2}\phi_{\tau,\xi}(z_{j}) \phi_{\tau,\xi}(z_{k}) \bigg)^{\frac{1}{2}}.
\end{align}
By Jensen inequality, we can pass expectation over $\sigma$ inside $T_{2,1}$ and expectation over $z$ inside $T_{2,2}$. Note $\sigma_{i}$ and $\sigma_{j}$ are independent variables with $\mathbb{E} \sigma_{i} = \mathbb{E}\sigma_{j} = 0$, and $||\phi_{\tau,\xi}||_{L_{2}}^{2} =1$.
\begin{align}
\mathbb{E}_{\sigma,z}\bigg[\,\, T_{2,2}\,\,\bigg] &\leqslant \big(\sum_{\tau>J^{2},|\xi|_{\infty} >J} a_{\tau,\xi}^{2} ||\phi_{\tau,\xi}||_{L_{2}}^{2} + \sum_{\tau,\tau^{\prime}>J^{2}} \sum_{|\xi|_{\infty}, |\xi^{\prime}|_{\infty}>J}a_{\tau,\xi}a_{\tau^{\prime},\xi^{\prime}}  ||\phi_{\tau,\xi} \phi_{\tau^{\prime},\xi}(z_{k})||_{L_1} \big)^{\frac{1}{2}} \\
&= \big(\sum_{\tau>J^{2},|\xi|_{\infty} >J} a_{\tau,\xi}^{2} \big)^{\frac{1}{2}}\hspace{3.2cm} - \text{ Orthogonality of } \phi_{\tau,\xi}(z) \ \\
&\leqslant ||P_{>J, >J^{2}}h||_{H^{1}_{t}(\mathbb{R};H^{1}_{x}(\mathbb{R}^{d}))}\\
&\leqslant C(\Omega,T) ||P_{>J,>J^{2}}h||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}\hspace{1.1cm} - \text{ space-time extension Lemma~\ref{space_time_extension} }\\
&\lesssim  RJ^{-(2p+q-3)}\sqrt{\rho}. \hspace{3.8cm} - \text{ stability estimate Proposition~\ref{prop:stability}}
\end{align}
Combining $T_{2,1}$ and $T_{2,2}$ all together, we obtain
\begin{equation}
T_{2} = T_{2,1} * \mathbb{E}_{\sigma,z}[T_{2,2}]\lesssim J^{-(2p+q-3)}\sqrt{\frac{\rho}{nm}} \label{T_2}.
\end{equation}
\textbf{Control of $T_{1}$}:\\
In this section, we stick with $h:= ext\,(u_{J} - u^{*})$. We use a chaining bound for metric entropy to bound $T_{1}$ using $L^2_{t}(\mathbb{R};L^2_{x}(\mathbb{R}^{d}))$ bracketing number, and note $L^2_{t}(\mathbb{R};L^2_{x}(\mathbb{R}^{d}))$ is equivalent to $L^2_{t,x}(\mathbb{R}\times \mathbb{R}^{d})$.  In particular, we construct a bracketing number for $J$ finitely many Fourier Coefficients $a_{\xi,\tau}$ in $L^{2}$ balls. \\\\
For $h_{1}, h_{2} \in \mathcal{U}_{J}(\rho)$,

\begin{align}
\big|\big|\,P_{J, J^{2}}h_{1} - P_{J,J^{2}}h_{2}\,\big|\big|_{L^{2}_{t}(0,T;L^{2}_{x}(
\Omega))}^{2} &= \big|\big| \sum_{1\leqslant |\xi|_{\infty}\leqslant J, 1\leqslant \tau \leqslant J^{2}} a^{(1)}_{\xi,\tau} \phi_{\xi,\tau}(x,t) - a^{(2)}_{\xi,\tau} \phi_{\xi,\tau}(x,t) \,\big|\big|_{L^{2}_{t}(0,T;L^{2}_{x}(
\Omega))}^{2}\\
&\lesssim 
\big|\big| \sum_{1\leqslant |\xi|_{\infty}\leqslant J, 1\leqslant \tau \leqslant J^{2}} (\,a^{(1)}_{\xi,\tau} - a^{(2)}_{\xi,\tau}\,) \phi_{\xi,\tau}(x,t) \,\,\big|\big|_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))}^{2} 
\\
&\leqslant \sum_{1\leqslant |\xi|_{\infty}\leqslant J, 1\leqslant \tau \leqslant J^{2}} \big|\,a^{(1)}_{\xi,\tau} - a^{(2)}_{\xi,\tau}\,\big|^{2}.
\end{align}
Hence we obtain 
\begin{equation}
\big|\big|\,P_{J}h_{1} - P_{J}h_{2}\,\big|\big|_{L^{2}_{t}(0,T;L^{2}_{x}(
\Omega))}^{2} \lesssim \sum_{1\leqslant |\xi|_{\infty} \leqslant J, 1\leqslant \tau \leqslant J^{2}} |a^{(1)}_{\xi,\tau} - a^{(2)}_{\xi,\tau}|^{2}. \label{packing-number-inequality}
\end{equation}
The inequality above suggests a control of finitely many spatial-temporal cofficients $a_{\xi,\tau}$ in $L^{2}$ ball of coefficient space is sufficient to construct an $\epsilon$-net for $h\in \mathcal{U}_{J}(\rho)$.\\\\
We want to construct $L^{2}$ packing number for the space of  finitely many Fourier coefficients $a_{\xi,\tau}$. Using standard $L^{2}$-packing for $L^{2}$ balls argument in Lemma \ref{lemma_F.6} and note the dimension of  coefficients are at most $J^{d+2}$, we have

\begin{align}
\log N(\mathcal{U}_{J}(\rho), ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon)
&\lesssim  \log(\frac{3}{\delta})^{J^{d+2}}= J^{d+2} \log(\frac{1}{\epsilon}).
\end{align}

With the above packing number at hand, we're ready to apply Bernstein Chaining in Theorem~\ref{Bernstein Chaining}. Before applying Bernstein Chaining, we nee to check finite second moment condition and finite $L_{\infty}$ norm condition.\\

From the lower bound of stability estimates in Proposition~\ref{prop:stability} and Lemma~\ref{J_truncation_estimates}, we can verify second moment condition for $P_{J}h\in \mathcal{U}_{J}(\rho)$
\begin{align}
\label{second-moment-condition}
||P_{J}h||_{L^{2}_{t}(\mathbb{R} ;L^{2}_{x}( \mathbb{R}^{d}))} \leqslant ||h||_{L^{2}_{t}(\mathbb{R} ;L^{2}_{x}( \mathbb{R}^{d}))}\lesssim C(\Omega,T) \sqrt{\rho B(\epsilon,\beta,\Omega,T,d)},
\end{align}
where $B(\epsilon,\beta,\Omega,T,d):= (1+\frac{\beta}{\beta_{0}})^{-1}$, $\beta_{0} =  e^{T/\epsilon} C^{2}(d,\epsilon,\Omega)$, and $C(d,\epsilon, \Omega)$ is the Cheeger constant here.\\

To verify $L_\infty$ condition, we use Lemma~\ref{J_truncation_estimates} to obtain
\begin{equation}
||P_{J}h||_{\infty}
\lesssim 
\begin{cases}
 R, \,\,\,\quad q>\frac{d}{2},\\
 J^{d+2}, \quad q\leqslant\frac{d}{2}.
\end{cases}
\label{L_infty_condition}
\end{equation}
Next we will incorporate bracketing numbers into the Dudley integral theorem (cf. Theorem \ref{theorem_A.3} ) to get
\begin{align}
D_{[]}&:=D_{[ ]}\bigg(\sqrt{\rho B(\epsilon,\beta,\Omega,T,d)},\,\, \mathcal{U}_{J}(\rho), \,\,||\cdot||_{L^{2}_{t,x}(\mathcal{P})}\bigg)\\
&=\displaystyle\int_{0}^{\sqrt{\rho B(\epsilon,\beta,\Omega,T,d)}} \sqrt{logN_{[ ]}\bigg(\epsilon, \mathcal{U}_{J}(\rho), ||\cdot||_{L^{2}_{t,x}(\mathcal{P})}\bigg)} \,\, d\epsilon\\
&\lesssim \int_{0}^{\sqrt{ \rho B(\epsilon,\beta,\Omega,T,d)}} J^{\frac{d+2}{2}} \sqrt{ \log(1+ \frac{1}{\epsilon})}\,\, d\epsilon
\end{align}
and
\begin{equation}
D_{[ ]}\lesssim J^{(d+2)/2}\sqrt{\rho B(\epsilon,\beta,\Omega,T,d)\log(1+ \sqrt{\frac{C_{2} \beta_{0}}{\rho \beta}}}),
\end{equation}
where $C_{2}$ is some appropriately chosen constant.
\\\\
Plugging second moment condition (\ref{second-moment-condition}) and $L^{\infty}$ condition (\ref{L_infty_condition}) into Theorem  \ref{Bernstein Chaining}, we obtain 
\begin{equation}
T_{1}: \lesssim \frac{1}{\sqrt{nm}}D_{[]} \bigg(1+ \frac{D_{[]}}{\sqrt{nm}||P_{J}h||_{L^{2}_{t}([0,T];L^{2}_{x}(\Omega))}^{2}} ||P_{J}h||_{\infty}\bigg).
\end{equation}
We obtain 
\begin{equation}
T_{1}\lesssim \frac{1}{\sqrt{nm}} J^{\frac{d+2}{2}} \sqrt{\rho B(\epsilon,\beta,\Omega,T,d)\log(1+ \sqrt{\frac{C_{2} \rho} {B(\epsilon,\beta,\Omega,T,d)}}}) + \tau(\rho, J),\label{T_1}
\end{equation}
where 
\begin{equation}
\tau(\rho, J)\lesssim \begin{cases} \frac{R}{nm} J^{2(d+2)}\log(1+ \sqrt{\frac{C_{2} \rho} {B(\epsilon,\beta,\Omega,T,d)}}),\hspace{0.6cm} q\leqslant\frac{d}{2},\\
\frac{R}{nm} J^{d+2}\log(1+ \sqrt{\frac{C_{2} \rho} {B(\epsilon,\beta,\Omega,T,d)}}),\hspace{1cm} q>\frac{d}{2}.
\end{cases}
\end{equation}
