\beta, \Omega,T,d)(1+\frac{\beta}{2\epsilon})J^{d+2}\frac{\log{(1+ C_{2}\sqrt{nm})}}{nm}\label{r_determined_2_p>d/2_part_1}\\
&\quad +  (1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)||u_{J}-u^{*}||_{{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}}^{2}+  \frac{Rs +1}{B(\epsilon,
\beta, \Omega,T,d)nm}
\label{r_determined_2_p>d/2_part_2}.
\end{align}
Similarly, with $r$ in (\ref{r_determined_2_p>d/2_part_1}) and (\ref{r_determined_2_p>d/2_part_2}), we obtain with probability $1-e^{-s}$,

\begin{align}
||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 &\lesssim_{R}  \bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]||u_{J}-u^{*}||_{{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}}^{2}\\& +  B(\epsilon,
\beta, \Omega,T,d)(1+\frac{\beta}{2\epsilon})\frac{J^{d+2}}{nm}\log{(1+C_{2}nm)}+ \frac{1+s}{nm} .
\end{align}
and we obtain in expectation
\begin{align}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 &\lesssim  \bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]||u_{J}-u^{*}||_{{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}}^{2}\\& +  B(\epsilon,
\beta, \Omega,T,d)(1+\frac{\beta}{2\epsilon})\frac{J^{d+2}}{nm}\log{(1+C_{2}nm)}+ \frac{1}{nm} .
\end{align}
Next, we want to control the approximation error $\underset{u_{J}\in \mathcal{U}_{J}}{\inf}\,\,||u_{J} - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}$ that appeared in Proposition \ref{localization}. Since our solution $u^{*}$ is defined in compact domain space-time domain $\Omega\times[0,T]$, it is sufficient to control $\bar{u}_{J}:=\prod_{J} ext\,u^{*}$, which is a projection of $u^{*}$ over $J$ truncated local basis extended to entire space-time domain $\mathbb{R}^{d}$ and $\mathbb{R}$. In light of extension Lemma~\ref{Sobolev_extension_theorem}, ext $u^{*}$ preserves Sobolev norm up to some constant depending on $\Omega$ and $[0,T]$, and together with assumption A3 in Appendix \ref{sec:main_assumptions}, we can show under Sobolev norm $||\cdot ||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}$, approximation errors are controllable.
\begin{lemma} Given $p,q \in \mathbb{Z}^{+}$ and $J,J^{\prime} \in\mathbb{Z}^{+}$. For any function $f(x,t)\in H^{p}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d})) $, there exists Spatial-Temporal approximation $f_{J, J^{\prime}}(x,t)$ in the space $\mathcal{F}_{J,J^{\prime}}\cap H^{p}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d})) $ such that the following approximation inequalities hold for $0\leqslant  p_{1} \leqslant p, 0\leqslant  q_{1} \leqslant q$,
\label{lemma_E.4}
\begin{equation}
||f-f_{J,J^{\prime}}||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2} \lesssim J^{-2(q-q_{1})}{J^{\prime}}^{-2(p-p_{1})}||f||_{H^{p}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d}))}^{2}.
\end{equation}
In particular, if $J^{\prime} = J^{2}$, 
\begin{equation}
||f-f_{J,J^{\prime}}||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2} \lesssim J^{-2(q+2p-q_{1}-2p_{1})}||f||_{H^{p}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d}))}^{2},
\end{equation}
where 
\begin{equation}
\mathcal{F}_{J,J^{\prime}}:=\bigg\{f \,\,\bigg{|} \,\, f \in V_{J,J^{\prime}}\cap H^{p}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d})) \bigg\}.
\end{equation}
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lemma_E.4}]
For any $f\in H^{p}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d}))$, there exists Spatial-temporal  representation in terms of $L_2$ basis in space-time domain $\Omega_{T}$,

\begin{equation}
f(x,t) = f_{J,J^{\prime}}(x,t) +  f_{J,>J^{\prime}}(x,t) +  f_{>J,J^{\prime}}(x,t) +  f_{>J,>J^{\prime}}(x,t).
\end{equation}
Where $f_{J,J^{\prime}}(x,t)$ is the truncated term and the rest are tail terms and $\phi_{\xi,\tau}(x,t)$ is basis of $L^2$ of product space of space and time 
\begin{equation}
f_{J,J^{\prime}}(x,t):= \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|\leqslant J^{\prime}} a_{\xi,\tau} \phi_{\tau}^{\xi}(t)\phi_{\xi}(x)
,\quad f_{J,>J^{\prime}}(x,t):= \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} a_{\xi,\tau} \phi_{\tau}^{\xi}(t)\phi_{\xi}(x),
\end{equation}
\begin{equation}
f_{>J,J^{\prime}}(x,t):= \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}} a_{\xi,\tau} \phi_{\tau}^{\xi}(t)\phi_{\xi}(x), \quad 
f_{>J,>J^{\prime}}(x,t):= \sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} a_{\xi,\tau} \phi_{\tau}^{\xi}(t)\phi_{\xi}(x).
\end{equation}
According to the definition of Sobolev norm (\ref{sobolev_norm_in_fourier_transform}) and definition of time-dependent Sobolev space in Appendix \ref{time_dependent_space}, we can rewrite the tailed error of Fourier approximation of $f(x,t)$ as the following

\begin{align}
||f(\cdot,t)-f_{J,J^{\prime}}(\cdot,t)||_{H^{q_{1}}_{x}(\mathbb{R}^{d})}^2 &= ||f_{>J,J^{\prime}}(\cdot,t) + f_{J,>J^{\prime}}(\cdot,t) + f_{>J,>J^{\prime}}(\cdot,t)||_{H^{q_{1}}_{x}(\mathbb{R}^{d})}^2 \\
& \lesssim\Bigl(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}}  + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \Bigl(1+|\xi|^{q_{1}}\Bigr)^{2}  a_{\xi,\tau}^2 \phi_{\tau}^{2}(t) \Bigr).
\end{align}\\
We then calculate $H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))$ norm and obtain
\begin{equation}
||f-f_{J,J^{\prime}}||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^d))}^2 \lesssim\Bigl(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}}  + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \Bigl(1+\tau^{p_{1}} \Bigr)^{2}\Bigl(1+\xi^{q_{1}}\Bigr)^{2}  a_{\xi,\tau}^2 \Bigr). 
\end{equation}
Using the highest order term $\tau^{2p_{1}}$ and $\xi^{2q_{1}}$ to bound above equality, we obtain 

\begin{align}
||f -f_{J,J^{\prime}}||_{{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}}^{2} &\lesssim \bigg(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}} + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \tau^{2p_{1}}\xi^{2q_{1}} a_{\xi,\tau}^2  \bigg)\\
&= \bigg(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}} + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \tau^{-2(p-p_{1})}\xi^{-2(q-q_{1})} \tau^{2p}\xi^{2q}a_{\xi,\tau}^2  \bigg)\\
&\lesssim J^{-2(p-p_{1})}{J^{\prime}}^{-2(q-q_{1})}|| f ||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2}.
\end{align}

Finally, we obtain the desired result
\begin{equation}
||f -f_{J,J^{\prime}}||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2} \lesssim J^{-2(p-p_{1})}{J^{\prime}}^{-2(q-q_{1})}|| f ||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2}.
\end{equation}
\end{proof}
If we can show $\bar{u}_{J}\in \mathcal{U}_{J}$, then it immediately follows from Lemma \ref{lemma_E.4} and space-time extension Lemma~\ref{space_time_extension}
\begin{align}
\underset{u_{J}\in \mathcal{U}_{J}}{\inf}\,\,||u_{J} - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}&\leqslant ||\bar{u}_{J} - ext\,u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2}\\
&\leqslant  ||\bar{u}_{J} - ext \,u^{*}||_{H^{1}_{t}(\mathbb{R};H^{1}_{x}(\mathbb{R}^{d}))}^{2}\lesssim R^{2}J^{-2(q+2p-3)}.
\end{align}
It remains to show $\bar{u}_{J}\in \mathcal{U}_{J}$. We note extension operator can preserve time-dependent Sobolev norm from Theorem \ref{space_time_extension} up to some constant $C(\Omega,T)$. Therefore, $\bar{u}_{J}$ satisfies boundedness assumption of time-dependent Sobolev norm in assumption A3 in Appendix \ref{sec:main_assumptions}, and $\bar{u}_{J}\in \mathcal{U}_{J}$.

Finally, we incorporate approximation errors into bound of excessive risk in expectation, leading to bias-variance trade-off.\\\\
On one hand, when $q\geqslant \frac{d}{2}$,
\begin{align}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 &\lesssim_{R} \bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]J^{-2(2p+q-3)}\label{bias-variance-tradeoff_1.1}\\ &+  B(\epsilon,
\beta, \Omega,T,d)(1+\frac{\beta}{2\epsilon})\frac{J^{d+2}}{nm}\log{(1+C_{2}nm)}+ \frac{1}{nm}.
\label{bias-variance-tradeoff_1.2}\end{align}
On other hand, when $q< \frac{d}{2}$,
\begin{align}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 &\lesssim_{R}\bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]J^{-2(2p+q-3)}\label{bias-variance-tradeoff_2.1}\\& + (1+ \frac{\beta}{2\epsilon} )B^{2}(\epsilon,
\beta, \Omega,T,d)\frac{J^{2(d+2)}}{nm}\log{(1+C_{2}nm)}\\&
+\frac{1}{B(\epsilon,
\beta, \Omega,T,d)nm}
\label{bias-variance-tradeoff_2.2}.\end{align}
Bias decreases as approximation accuracy controlled by $J$ increases, while variance becomes larger when introducing high-frequency statistics information. Therefore, we need to find trade-off between bias and variance to balance variance and bias together with regularization parameter.

Similarly, we also need to balance regularization $B(\epsilon, \beta, \Omega, T)$ and $1+\frac{\beta}{\epsilon}$ on either variance or bias, and we derive regularization threshold $\beta^{*} \approx \log (1+C_{2}N)^{\frac{b}{a+2b}}N^{\frac{a}{a+2b}} \beta_{0}$ in \eqref{optimal_beta_q<d/2} of Appendix \ref{E.3}. We notice $\beta^{*}$ is a small constant and therefore regularization falls into the regime of bias regularization for the most of times. If $0< \beta< \beta^{*}$, $\beta$ is in the regime of regularizing variance; if $\beta>\beta^{*}$, $\beta$ is in the regime of regularizing bias. 

Now, we're ready to prove upper bound on estimation error.

\subsection*{Proof of Theorem~\ref{upper_bound}}
\label{appendix_L}
\label{section_L}
