In this section, we discuss the bias-variance trade-off for two different regularity condition: $q\leqslant \frac{d}{2}$ and $q>\frac{d}{2}$. First, we focus on the regularization regime when $q\leqslant \frac{d}{2}$.
According to Lemma \ref{lemma_E.4} with $J^{\prime} = J^{2}$ and assumption A1 of Appendix \ref{sec:main_assumptions}, we have 
\begin{equation}
\,\,\underset{u_{J}}{\inf}\,\,||u_{J} - u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^{2} \lesssim J^{-2(2p+q-3)}R^{2}.
\label{approximation_error}
\end{equation}
Substituting approximation error (\ref{approximation_error}) into Proposition \ref{high_probability_bound_on_excess_risk}, we obtain the following\\\\
When $q<\frac{d}{2}$,
\begin{align}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim_{R}  &\underbrace{(1+ \frac{\beta}{2\epsilon} )B^{2}(\epsilon,
\beta, \Omega,T,d)\frac{J^{2(d+2)}}{nm} \log{(1+C_{2}nm)}}_{\text{Variance}}\\
& + \underbrace{\bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]J^{-2(2p+q-3)}}_{\text{Bias}} + \frac{1}{B(\epsilon,
\beta, \Omega,T,d)nm}
\label{excess_risk_bound_unbalanced}.
\end{align}
When $q\geqslant\frac{d}{2}$,
\begin{align}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 & \lesssim  \underbrace{B(\epsilon,
\beta, \Omega,T,d)(1+\frac{\beta}{2\epsilon})\frac{J^{d+2}}{nm}\log{(1+C_{2}nm)}}_{\text{bias}} \\ &+ \underbrace{\bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]J^{-2(2p+q-3)}R^{2}}_{\text{variance}}+ \frac{1}{nm}.
\end{align}
\subsection{Regime of regularization ($q< \frac{d}{2}$)}\label{E.3}\label{regime_regularization_1}
Here we want to find the regimes for the regularization parameter $\beta$ with respect to variance scaling $J^{2(d+2)}$.
Let $N:=nm$ denote the total sample size and the excess risk upper bound by . Consider the above excess-risk bound \eqref{excess_risk_bound_unbalanced}, we set $a:=2(d+2)$ and $b:=2(2p+q-3)$,
\begin{align}
\label{eq:err_beta_1}
&\mathcal{E}(J,\beta)
\;\lesssim_{R}
(1+ \frac{\beta}{2\epsilon} )B^{2}(\epsilon,
\beta, \Omega,T,d)\,\frac{J^{a}}{N}\log (1+C_{2}N)\\
&\quad\quad\quad\quad+\;
\bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
\beta, \Omega,T,d)\bigg]\,J^{-b}\;+\; \frac{1}{B(\epsilon,
\beta, \Omega,T,d)nm},
\end{align}
where the $\beta$-dependent variance term is
\begin{equation}
\label{optimal_beta_q<d/2}
B(\epsilon,
\beta, \Omega,T,d)
=
\Bigl(\frac13+\frac{\beta e^{-T/\varepsilon}}{C^2(d,\varepsilon,\Omega)}\Bigr)^{-1}
=
\Bigl(\frac13+\frac{\beta}{\beta_0}\Bigr)^{-1},
\qquad
\beta_0:=C^2(d,\varepsilon,\Omega)\,e^{T/\varepsilon}.
\end{equation}
Thus $\beta$ decreases the variance term $B(\beta)$, but increases the bias term
$\bigl(1+\beta/(2\varepsilon)\bigr)$.
\subsubsection{Optimal truncation level for a given $\beta$}
Balancing variance and bias in (\ref{eq:err_beta_1})
 yields
\begin{equation}
\label{J_*1}
J_{1,*}(\beta)
\;\asymp\;
\Biggl[
\frac{N}{\log (1+C_{2}N)}
\cdot
\frac{1}{(1+ \frac{\beta}{2\epsilon} )B^{2}(\epsilon,
\beta, \Omega,T,d)}\cdot \bigg(1+(1+\frac{\beta}{2\epsilon})B(\epsilon,
\beta, \Omega,T,d)\bigg)\Biggr]^{\frac{1}{a+b}}
\end{equation}
and the corresponding optimized bound becomes
\begin{equation}
\label{eq:ErrStar}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim_{R} \Bigl(1+\frac{\beta_{0}}{2\epsilon}\Bigr)\cdot
\Bigl(\frac{\log (1+C_{2}N)}{N}\Bigr)^{\frac{b}{a+b}}
\cdot
(\frac{\beta_{0}}{\beta_{0}+\beta})^{\frac{b}{a+b}}
 + (1+\frac{\beta}{\beta_{0}}) \frac{1}{N}.
\end{equation}
\subsubsection{Case I (From Unregularized to Mildly Regularized Regime): $ 0\leqslant \beta\leqslant\beta_{0} $}
In this regime where energy regularization can only improve the rate up to some constant, we obtain sub-optimal rate 
\begin{equation}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim_{R}  \Bigl(1+\frac{\beta_{0}}{2\epsilon}\Bigr)\cdot\Bigl(\frac{\log (1+C_{2}N)}{N}\Bigr)^{\frac{b}{a+b}}.
\end{equation}

\subsubsection{Case II (Optimal Rate with fine-tuned $\beta$): $\beta=\beta_{*}
$} when we balance $\beta$, we obtain optimal rate\begin{equation}\beta^{*} \approx \log (1+C_{2}N)^{\frac{b}{a+2b}}N^{\frac{a}{a+2b}} \beta_{0}\label{beta_threshold}\end{equation} and plugging $\beta^{*}$ back, we obtain the following rate
\begin{equation}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim_{R}  \Bigr(\frac{\sqrt{\log (1+C_{2}N)}}{N} \Bigr)^{\frac{2b}{a+2b}}.
\end{equation}
In this regime, regularization reduces the variance with mildly inflating the bias term. 
\subsubsection{Case III (Variance-improving Regime): $\beta_{0}<\beta<\beta^{*}$}
In this scenario, variance is reduced to improve the rate
\begin{equation}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim_{R} \Bigl(1+\frac{\beta_{0}}{2\epsilon}\Bigr)\cdot\Bigl(\frac{\log (1+C_{2}N)}{N}\Bigr)^{\frac{b}{a+b}}
\cdot
(\frac{\beta_{0}}{\beta_{0}+\beta})^{\frac{b}{a+b}}.
\end{equation}

\subsubsection{Case V (Bias-inflating Regime): $\beta^{*}<\beta<\infty$}
In this scenario, variance is inflated to make the rate worse
\begin{equation}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim_{R}  (1+\frac{\beta}{\beta_{0}}) \frac{1}{N}.
\end{equation}
