\begin{align}
\mathbb{E}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 &\lesssim  \bigg[1+(1+\frac{\beta}{2\epsilon}) B(\epsilon,
