J_{2,*}(\beta)
\;\asymp\;
\Biggl[
\frac{N}{\log (1+C_{2}N)}
\cdot
\frac{1+\frac{\beta}{\beta_{0}}}{1+\frac{\beta}{2\epsilon}}\cdot \bigg(1+\frac{1+\frac{\beta}{2\epsilon}}{1+\frac{\beta}{\beta_{0}}}\bigg)\Biggr]^{\frac{2}{a+2b}}
