According to the definition of Sobolev norm (\ref{sobolev_norm_in_fourier_transform}) and definition of time-dependent Sobolev space in Appendix \ref{time_dependent_space}, we can rewrite the tailed error of Fourier approximation of $f(x,t)$ as the following

\begin{align}
||f(\cdot,t)-f_{J,J^{\prime}}(\cdot,t)||_{H^{q_{1}}_{x}(\mathbb{R}^{d})}^2 &= ||f_{>J,J^{\prime}}(\cdot,t) + f_{J,>J^{\prime}}(\cdot,t) + f_{>J,>J^{\prime}}(\cdot,t)||_{H^{q_{1}}_{x}(\mathbb{R}^{d})}^2 \\
& \lesssim\Bigl(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}}  + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \Bigl(1+|\xi|^{q_{1}}\Bigr)^{2}  a_{\xi,\tau}^2 \phi_{\tau}^{2}(t) \Bigr).
\end{align}\\
We then calculate $H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))$ norm and obtain
\begin{equation}
||f-f_{J,J^{\prime}}||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^d))}^2 \lesssim\Bigl(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}}  + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \Bigl(1+\tau^{p_{1}} \Bigr)^{2}\Bigl(1+\xi^{q_{1}}\Bigr)^{2}  a_{\xi,\tau}^2 \Bigr). 
\end{equation}
Using the highest order term $\tau^{2p_{1}}$ and $\xi^{2q_{1}}$ to bound above equality, we obtain 

\begin{align}
||f -f_{J,J^{\prime}}||_{{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}}^{2} &\lesssim \bigg(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}} + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \tau^{2p_{1}}\xi^{2q_{1}} a_{\xi,\tau}^2  \bigg)\\
&= \bigg(\sum_{|\xi|_{\infty}> J} \sum_{|\tau|> J^{\prime}} + \sum_{|\xi|_{\infty}> J} \sum_{|\tau|\leqslant J^{\prime}} + \sum_{|\xi|_{\infty}\leqslant J} \sum_{|\tau|> J^{\prime}} \tau^{-2(p-p_{1})}\xi^{-2(q-q_{1})} \tau^{2p}\xi^{2q}a_{\xi,\tau}^2  \bigg)\\
&\lesssim J^{-2(p-p_{1})}{J^{\prime}}^{-2(q-q_{1})}|| f ||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2}.
\end{align}

Finally, we obtain the desired result
\begin{equation}
||f -f_{J,J^{\prime}}||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2} \lesssim J^{-2(p-p_{1})}{J^{\prime}}^{-2(q-q_{1})}|| f ||_{H^{p_{1}}_{t}(\mathbb{R};H^{q_{1}}_{x}(\mathbb{R}^{d}))}^{2}.
\end{equation}

\label{prop:parabolic-balance}
Given functional space $V_{J,J^{2}}$ defined in \ref{functional_space}, the evaluation map of our empirical loss $\hat{L}_{\epsilon,\beta}$ is injective only if 
\begin{equation}\label{eq:n-lower}
n\geqslant J^2.
\end{equation}
Furthermore, it is necessary to require 
\begin{equation}
n\gtrsim m^{2/d} \label{eq:m-upper}
\end{equation}
up to logarithmic factor for theorem 3.1 hold.

The main idea of our proof directly refers to standard construction tools from \cite{Tsybakov:1315296} with additional tool from PDE theory Theorem~\ref{Duhamel_principle}. By definition of $\mathcal{U}$ and $u^{*}$ in (\ref{functional_space}), for any ground truth solution $u^{*}\in \mathcal{U}$, we can always find data $f = Lu^{*} \in \mathcal{F}$ with which we can construct estimator for $\hat{u}$. The construction is following:
We follow our convention to treat time domain as another dimension so we write $d+1$ hypercube as $\mathcal{D}_{T} = [0,1]^{d}\times [0,1]$. According to regularity theory (Theorem~\ref{higher_regulairty_thm}), given forcing function $f\in \mathcal{F}$ and initial condition $u_{0}^{*}\in H^{2s+1}([0,1]^{d})$, there exists solution $h\in \mathcal{U}$ defined in (\ref{functional_space}) corresponding to this $f$. Our $h$ here is not necessarily a smooth function in the regular sense, but it is smooth in the Sobolev sense and its smoothness is determined by the functional space of forcing $\mathcal{F}$ and the initial data $u_{0}^{*}$. In particular, $h$ has the following smoothness property

 \begin{equation}
    \frac{d^{p}h}{dt^{p}}\in L^{2}(0,1;H^{2s+2-2p}([0,1]^{d})),  0\leqslant p\leqslant s,\, s\geqslant 1, s,q\in \mathbb{Z}.
\end{equation}

This implies
$\frac{dh}{dt}$ and $\triangle h$ exists in $L^{2}_{t,x}([0,1]^{d}\times[0,1])$ sense and $h\in H^1(0,T;H^{1}([0,1]^{d})):= H^{1}_{t}H^{1}_{x}$. Moreover, since $f$ and is non-zero, then $h$ can't be identitically zero for any $(x,t)\in [0,1]^{d}\times [0,1]$. For $f_{0}$, there exists unique solution $u_{f_{0}}:= h$.We also note the difference between $f_{0}$ and other $f_{k}$ is smooth perturbation, because its convolution with heat kernel, by Duhamel's Principle \ref{Duhamel_principle}, is smooth. Therefore, we then pick some function $g(x,t)$ for this perturbation such that $\frac{\partial g}{\partial t}$ and $\nabla g$ are not identically zero.

Let $r$ be the number of grid size on hypercube $[0,1]^{d}$ to be determined later. According to scaling invariance property Corollary~\ref{scaling_invariant} of $h$, $g(x,t)$ is a solution to heat equation if only if $g(\frac{x}{r}, \frac{t}{r^{2}})$ is a solution to heat equation. Therefore, we should have $r^{2}$ number of grid on unit time horizon $[0,1]$ while $r$ number of grid on spacial hypercube $[0,1]^{d}$ so that temporal scaling by $\frac{1}{r^2}$ can match with spacial scaling $\frac{1}{r}$ in upcoming construction of hypothesis test.

We define our hypothesis as the following
\begin{align}
u_{f_{k}}(x,t) &= h(x,t) +\sum_{j\in[r^{2}]} \sum_{i\in[r]^{d}}c\,\tau_{i,j}^{(k)}\, w^{2p+q} g(\frac{x-x^{i}}{w}, \frac{t-t^{j}}{w^{2}}),\, w=\frac{1}{2r},\,k=1,...,2^{\frac{r^{d+2}}{8}},\\
u_{f_0}(x,t) &= h(x,t),
\end{align} 
where $c,\lambda$ are some constants.

It is readily to check the collection of functions $\{g(\frac{x-x^{i}}{w},\frac{t-t^{j}}{w^{2}})\}_{i,j}$ has disjoint compact support for pair $(i,j)$ and $h(\frac{x-x^{i}}{w},\frac{t-t^{j}}{w^{2}})$ satisfies heat equation given initial condition $u_{0}^{*}$ and $f$. Therefore, $u_{k}$ satisfies the heat equation as well.

We discretize the space $[0,1]^{d}$ by defining a collection of vectors $\{\,x^{i}: x^{i} =(x^{i}_{1}, ..., x^{i}_{d}), i \in [r]^{d}\,\}\subset [0,1]^{d}$ to have coordinates $x_{l}^{i}: =\frac{i_{l}-1}{r}$, $i_{l} \in [r]$, $l=1,...,d$. Again, we similarly define another collection of numbers $\{ t^{j}: t^{j} = \frac{j-1}{r^{2}},\,\,j\in [r^{2}] \}\subset[0,1]$. According to the Varshamov-Gilbert lemma, there exists $\frac{r^{d+2}}{8}$ many $0$-$1$ sequences $\tau^{(1)}\,,...,\,\tau^{(2^{r^{d+2}/8})} \in \{0,1\}^{r^{d+2}}$ such that   $||\,\tau^{k} - \tau^{k^{\prime}}\,||^{2}\geqslant \frac{{r^{d+2}}}{8}\,,k\neq k^{\prime}$. Then we cast solving parabolic PDEs Problem into high-dimensional multiple hypothesis testing on hypercube $[0,1]^{d}\times [0,1]$ which considers all mappings $\Phi$ from $nm$ sampled data on domain $\Omega_{T}$ to the hypothesis 
\begin{equation}
\Phi: (x,t)\in(\mathbb{R})^{{d+1}^{\otimes{nm}}} \times \mathbb{R}^{\otimes nm} \rightarrow U:= \big\{u_{k}(x,t) \mid k=1,2,...,2^{\frac{r^{d+2}}{8}} \big\}.
\end{equation}
We recall Fano's inequality
\begin{equation}
P(\hat{u} \neq u) \geqslant 1 - \frac{I(U;X) + \log{2}}{ \log(|U|)}, \quad\quad \text{for any estimator } \hat{u}.
\end{equation}
We obtain a constant lower bound of $P(u_{k}^{\prime}\neq u_{k})$ by bounding KL-divergence from above 
\begin{equation}
I(U;X) \leqslant \frac{1}{|U|} \sum_{(x,t)} \sum_{u_{k}\neq u_{0}
} D_{KL}(\mathbb{P}_{u_{k}}||\mathbb{P}_{u_{0}}).
\end{equation}
where $P_{u_{k}}$ is a joint distribution of the sampled data $((x,t),f_{k}(x,t))$ for hypothesis $u_{k}$ corresponding to noisy observation of force function $f_{k}$, and $(x,t)\sim P_{0}$, $P_{0}$ is a product of Lebesgue measure on $[0,1]^{d}$ and Lebesgue measure on $ [0,1]$; $ y_{k}=f_{k}(x,t)+ \epsilon$ where $\epsilon$ is an i.i.d Gaussian noise for each location point $(x,t)$, and so $y_{k} \sim Q_{k}$, $Q_{k}$ is probability measure of standard normal random variable with mean $f_{k}$. Therefore, we can write $W_{f_{k}}:= P_{0}\otimes Q_{k}$, where $P_{0}$ is independent from $Q_{k}$ across tensor product\\
Note $\triangle u_{k} - \frac{\partial u}{\partial{t}} = f_{k}$ and $\triangle u_0 - \frac{\partial u_{0}}{\partial t} = \triangle h - \frac{\partial h}{\partial t} = f_{0}$. 
\begin{align}
D_{KL}(W_{f_{k}}||W_{f_{0}}) &= D_{KL}(P_{0}\otimes Q_{k} || P_{0}\otimes Q_{0}) \\
& = \mathbb{E} \log(\frac{dQ_{k}}{dQ_{{0}}})\\
&= ||f_{k} - f_{0}||_{L^{2}_{t,x}([0,1]\times[0,1]^{d})}^{2}\\
& = ||(\triangle u_{f_k} - \frac{\partial u_{f_k}}{\partial{t}}) - (\triangle u_{f_0} - \frac{\partial u_{f_0}}{\partial{t}}) ||_{L^{2}_{t,x}([0,1]\times[0,1]^{d})}^{2}\\
&= \bigg|\bigg|\sum_{i\in[r^{d+1}]}c\,\tau_{i}^{(k)}\, w^{2p+q-1} \Big( g_{t}(\dfrac{x-x^{i}}{w}, \frac{t-t^{j}}{w^{2}}) - \triangle g(\dfrac{x-x^{i}}{w}, \frac{t-t^{j}}{w^{2}}) \Big) \bigg|\bigg|_{L^{2}_{t,x}([0,1]\times[0,1]^{d})}^{2} \\
&\leqslant  c^2 w^{2(2p+q-3)}  \big|\big|g_{t} - \triangle g\big|\big|_{L^{2}_{t,x}([0,1]\times[0,1]^{d})}^{2} \\
&\lesssim \frac{c^2}{r^{2(2p+q-3)}}.
\end{align}
Next, we want to use energy estimate from Theorem 5 in chapter 7.1 of \cite{evans}, which upper bounds $u_{k}$ using $f_{k}$. Note $u(0,x) =0$ in our setting, so we have 
\begin{equation}
||u_{k} - u_{0}||^{2}_{L^{2}([0,1];L^{2}([0,1]^{d}))} \leqslant C ||f_{k} - f_{0}||^{2}_{L^{2}([0,1];L^{2}([0,1]^{d}))} \lesssim\frac{c^2}{r^{2(2p+q-3)}}.
\end{equation}

With $r = [(nm)^{\frac{1}{2(2p+q-3)+d+2}}]$, 
\begin{equation}
\mathbb{P}(u_{k} \neq u^{\prime}_{k} )\geqslant 1-\dfrac{nmD_{KL}(\mathbb{P}_{u}||\mathbb{P}_{u^{\prime}})}{\log(|U|)}\geqslant 1-\dfrac{\frac{8c^2}{r^{2(2p+q-3)}}}{r^{d+2}\log 2} =1-\dfrac{8c^2 }{r^{2{(2p+q-3)}+d+2} \log{2}}.
\end{equation}
We then choose large $c$ and $\lambda$ such that $\mathbb{P}(u_{k} \neq u_{k}^{\prime} )\geqslant \dfrac{1}{2}$.Finally, we check separation condition under the evaluation metric $H^{1}_{t}H^{1}_{x}$ for hypothesis $u_{k}$ and $u_{k}^{\prime}$
\begin{equation}
||u_{k}- u^{\prime}_{k}||_{H^{1}_{t}H^{1}_{x}}^{2} = H(\tau^{k},\tau^{k^{\prime}}) c^{2} w^{2(2p+q-3)}||\,g (\frac{x-x^{i}}{w},\frac{t-t^{j}}{w^{2}}))\,||_{L^2_{t,x}([0,1]^{d}\times [0,1])}^{2} w^{d+2} \gtrsim  r^{-2(2p+q-3)}.
\end{equation}
Plugging in $r= [(nm)^{\frac{1}{2(2p+q-3)+d+2}}]$ and $2p+q=2s+2$, we obtain
\begin{equation}
\underset{\hat{u}}{\inf}\,\,\underset{u^{*}\in H^{s}(\Omega)}{\sup}\big|\big|\, \hat{u} - u^{*}\,\big|\big|_{H^{1}_{t}(0,1;H^{1}_{x}([0,1]^{d})}^{2} \gtrsim {(nm)}^{-\frac{2(2p+q-3)}{2(2p+q-3)+d+2}} ={(nm)}^{-\frac{4s-2}{4s+d}}.
\end{equation}

We fix $\epsilon>0$,\,\,$s\geqslant 1$ and $2p+q=2s+2$ for $0\leqslant p \leqslant s$. According to Theorem~\ref{thm_3.1}, regardless of the relation between $p$ and $d$, as long as we choose
\begin{equation}\lambda^{*}:=\log (1+C_{2}nm)^{\frac{4s-2}{4s+d}}(nm)^{-\frac{2+d}{4s+d}} e^{T/\epsilon}.
\end{equation}
Our estimation rate becomes optimal as follows
\begin{equation}
\underset{}{\mathbb{E}}||\hat{u}_{J}- u^{*}||_{H^{1}_{t}(0,T;H^{1}_{x}(\Omega))}^2 \lesssim \Bigl(\frac{\log (1+C_{2}nm)}{nm}\Bigr)^{\frac{4s-2}{4s+d}}.
\end{equation}
Thanks to the stability estimate in Proposition~\ref{prop:stability}, excess risk is upper bounded by estimation error
\begin{equation}
\underset{}{\mathbb{E}}\,\, L_{\epsilon,\beta}(\hat{u}_{J})-L_{\epsilon,\beta}(u^{*}) \lesssim  \frac{e^{T/\epsilon}}{\epsilon}\Bigl(\frac{\log (1+C_{2}nm)}{nm}\Bigr)^{\frac{4s-2}{4s+d}}.
\end{equation}

\label{lemma_E.5} Given the functional spaces defined above, the generalization error bound is upper bound by their Rademacher Complexities as follows

\begin{equation}
\mathbb{E}\Delta \mathcal{E}_{S,gen} \leqslant 2[\, \mathcal{R}_{N}(\mathcal{G}_{data}) + \mathcal{R}_{N}(\mathcal{G}_{energy}) + \mathcal{R}_{N}(\mathcal{G}_{correction})\,].
\end{equation}

\begin{proof}[Proof of Lemma~\ref{lemma_E.5}]
    Fix $\epsilon>0$ and $\beta = \beta_{reg}$ and denote $N=nm$.
\begin{align}
\mathbb{E}\Delta\mathcal{E}_{S,gen}\,&\leqslant \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |L_{\epsilon,\beta}(\hat{u}_{S}) - \hat{L}_{\epsilon,\beta}(\hat{u}_{S})|\\
&\leqslant \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |\mathcal{E}_{data} - \mathcal{E}_{data,n}| + \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |\mathcal{E}_{energy} - \mathcal{E}_{energy,n}| + \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |\mathcal{E}_{data} - \mathcal{E}_{data,n}|\\
&\leqslant \mathbb{E}\,\bigg|\frac{1}{nm} \sum_{i=1,j=1}^{nm}g_{data}(x_{ij},t_{j}) - \mathbb{E} [g_{data}]\,\bigg|\\
&\quad+ \mathbb{E}\,\bigg|\frac{1}{nm} \sum_{i=1,j=1}^{nm}g_{correction}(x_{ij},t_{j}) - \mathbb{E} [g_{correction}]\,\bigg|\\
&\quad\ + \mathbb{E}\,\bigg|\frac{1}{nm} \sum_{i=1,j=1}^{nm}g_{energy}(x_{ij},t_{j}) - \mathbb{E} [g_{energy}]\,\bigg|.
\end{align}
Thanks to Lemma ~$\ref{lemma_F.2}$, we have 
\begin{align}
\mathbb{E}\Delta\mathcal{E}_{S,gen}\,&\leqslant 2\mathcal{R}_{N}(\mathcal{G}_{data}) + 2\mathcal{R}_{N}(\mathcal{G}_{energy}) + 2\mathcal{R}_{N}(\mathcal{G}_{correction}).
\end{align}
Next we apply Dudley's theorem (cf. Theorem~\ref{theorem_A.3}) to bound the $\epsilon_{1}$-covering number of the $\mathcal{R}_{N}(\mathcal{G}_{data})$, $\mathcal{R}_{N}(\mathcal{G}_{energy})$, and $\mathcal{R}_{N}(\mathcal{G}_{correction})$.
\end{proof}

According to the Lemma \ref{lemma_E.5}, it is essential to bound Rademacher complexities to control the generalization error bound $\mathcal{E}_{S,gen}$. The idea is to bound the Rademacher complexities in terms of the metric entropy by using the well-known Dudley theorem \cite{Dudley1967TheSO}.

Fix $\epsilon>0$ and $\beta = \beta_{reg}$ and denote $N=nm$.
\begin{align}
\mathbb{E}\Delta\mathcal{E}_{S,gen}\,&\leqslant \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |L_{\epsilon,\beta}(\hat{u}_{S}) - \hat{L}_{\epsilon,\beta}(\hat{u}_{S})|\\
&\leqslant \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |\mathcal{E}_{data} - \mathcal{E}_{data,n}| + \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |\mathcal{E}_{energy} - \mathcal{E}_{energy,n}| + \mathbb{E} \underset{u\in \mathcal{U}}{\sup} |\mathcal{E}_{data} - \mathcal{E}_{data,n}|\\
&\leqslant \mathbb{E}\,\bigg|\frac{1}{nm} \sum_{i=1,j=1}^{nm}g_{data}(x_{ij},t_{j}) - \mathbb{E} [g_{data}]\,\bigg|\\
&\quad+ \mathbb{E}\,\bigg|\frac{1}{nm} \sum_{i=1,j=1}^{nm}g_{correction}(x_{ij},t_{j}) - \mathbb{E} [g_{correction}]\,\bigg|\\
&\quad\ + \mathbb{E}\,\bigg|\frac{1}{nm} \sum_{i=1,j=1}^{nm}g_{energy}(x_{ij},t_{j}) - \mathbb{E} [g_{energy}]\,\bigg|.
\end{align}
Thanks to Lemma ~$\ref{lemma_F.2}$, we have 
\begin{align}
\mathbb{E}\Delta\mathcal{E}_{S,gen}\,&\leqslant 2\mathcal{R}_{N}(\mathcal{G}_{data}) + 2\mathcal{R}_{N}(\mathcal{G}_{energy}) + 2\mathcal{R}_{N}(\mathcal{G}_{correction}).
\end{align}
Next we apply Dudley's theorem (cf. Theorem~\ref{theorem_A.3}) to bound the $\epsilon_{1}$-covering number of the $\mathcal{R}_{N}(\mathcal{G}_{data})$, $\mathcal{R}_{N}(\mathcal{G}_{energy})$, and $\mathcal{R}_{N}(\mathcal{G}_{correction})$.

\label{lemma_E.6}
Let $\mathcal{N}(\mathcal{F}, \rho ,\epsilon_{1})$ be $\epsilon_{1}$-covering number for functional space $\mathcal{F}$ under evaluation metric $\rho$.  When $\rho:=||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))}$, then
\begin{align}
&\log N(\mathcal{G}_{data}, \rho,\epsilon_{1}) \lesssim  J^{d+2}\bigg[\log{\frac{1}{\epsilon_{1}}} + 2d \log{J} \bigg], \\
&\log N(\mathcal{G}_{energy}, \rho,\epsilon_{1}) \lesssim_{R,F}  J^{d+2}\bigg[\log{\frac{\beta}{\epsilon\cdot\epsilon_{1}}} + 4dq\log{J} \bigg],\\
&\log N(\mathcal{G}_{correction}, \rho,\epsilon_{1}) \lesssim_{R,T}  J^{d+2}\bigg[ \log{\frac{\beta}{\epsilon \cdot \epsilon_{1}}} + 4dq \log{J}\bigg].
\end{align}

Our estimator is defined as $\hat{u} :=\hat{u}_{\theta}=\hat{u}_{J}$, which is discussed in \eqref{empirical_loss_function} and \eqref{parametrized_function_class}). Before we dive into our proof, we want to define the following relevant functional spaces:
\begin{align}
\mathcal{A}&: = \{\,a \mid a:= a_{\xi,\tau}, ||a_{\xi,\tau}||_{2}\leqslant R\,\},\\
\mathcal{G}_{data,1}&: = \{\,g \mid g:=\nabla u_{t} -\nabla u_{t}^{*}, u^{*},u\in \mathcal{U}\,\},\\
\mathcal{G}_{energy,1}&: = \{\,g \mid g:= \frac{\beta \cdot e^{-\frac{t}{\epsilon}}}{2} |u_{t}|^{2}, u\in \mathcal{U}_{J}\,\},\\
\mathcal{G}_{energy,2}&: = \{\,g \mid g:= \frac{\beta\cdot e^{-\frac{t}{\epsilon}}}{2\epsilon} |\nabla u|^{2}, u\in \mathcal{U}_{J}\,\},\\
\mathcal{G}_{energy,2}&: = \{\,g \mid g:= -\frac{\beta\cdot e^{-\frac{t}{\epsilon}}}{\epsilon} fu, u\in \mathcal{U}_{J}, \sup_{t,x}|f|\le F\,\},\\
\mathcal{G}_{correction,1}&: = \{\,g \mid g:= \beta e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,T)u(x,T),\,\, u^{*},u\in \mathcal{U}_{J}\,\},\\
\mathcal{G}_{correction,2}&: = \{\,g \mid g:= \beta e^{-\frac{t}{\epsilon}}u^{*}_{tt}u,\,\, u^{*},u\in \mathcal{U}_{J}\,\}.
\end{align}

We first obtain covering number for $\mathcal{G}_{data}$. It is sufficient to focus on $\nabla \hat{u}_{t} -\nabla u_{t}^{*}$ in data fitting term because it contains largest metric entropy compared to other terms due to loss of space-time derivatives.
\begin{equation}
\bigg|\,(\nabla \hat{u}_{t}^{1} -  \nabla u_{t}^{*}) - (\nabla \hat{u}_{t}^{2} -  \nabla u_{t}^{*})\,\bigg|=\bigg|\,\nabla \hat{u}_{t}^{1} - \nabla \hat{u}_{t}^{2}\,\bigg| \leqslant  \sum_{1\leqslant|\xi|,\tau \leqslant J} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2} |\cdot|\xi|\cdot|\tau |\cdot\phi_{\xi,\tau}(x,t).
\end{equation}
According to orthogonality property of local basis $\phi_{\xi,\tau}(x,t)$ , we have 
\begin{align}
||\,\nabla \hat{u}_{t}^{1} - \nabla \hat{u}_{t}^{2}\,||_{L^{2}_{t}(\mathbb{R}; L^{2}_{x}(\mathbb{R}^{d}))}^{2}& \leqslant  \sum_{1\leqslant|\xi|_{\infty}\leqslant J,1\leqslant \tau \leqslant J^{2}} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2} |^{2}\cdot|\xi|^{2}\cdot|\tau |^{2 } \\& \leqslant J^{2(d+2)} \sum_{1\leqslant|\xi|_{\infty}\leqslant J,1\leqslant \tau \leqslant J^{2}} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2} |^{2}.
\end{align}

The inequality above suggests a control of finitely many spatial-temporal cofficients $a_{\xi,\tau}\in \mathcal{A}$ in $L^{2}$ ball of coefficient space is sufficient to construct an $\epsilon_{1}$-net for $g\in \mathcal{G}_{data,1}$.Let $\delta:= \frac{\epsilon_{1}}{J^{d+1}}$, we want to construct $L^{2}$ packing number for the space of  finitely many Fourier coefficients $a_{\xi,\tau}$. Using standard $L^{2}$-packing for $L^{2}$ balls argument in Lemma ~\ref{lemma_F.6} and note the dimension of coefficients of local basis representation are at most $J^{d+1}$, we have

\begin{equation}
\log N(\mathcal{A}, ||\cdot||_2,\delta)
\lesssim  \log(\frac{J^{d+2}}{\epsilon_{1}})^{J^{d+2}}= J^{d+2}\bigg[\log{\frac{1}{\epsilon_{1}}} + (d+2)\log{J}\bigg].
\end{equation}

In this way, we obtain $\delta$-covering number for the functional space $\mathcal{G}_{data,1}$
\begin{equation}
\log N(\mathcal{G}_{data,1}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) \lesssim
\log N(\mathcal{A}, ||\cdot||_{2},\delta) \lesssim  J^{d+2}\bigg[\log{\frac{1}{\epsilon_{1}}} + (d+2)\log{J}\bigg].
\end{equation}
Next we omit the same procedure applied to $\mathcal{G}_{energy}$ and $\mathcal{G}_{correction}$. In similar fashion, we have the following elementary estimates 
\begin{align}
|g_{energy,1}|&=\bigg|\frac{\beta \cdot e^{-\frac{t}{\epsilon}}}{2} |\hat{u}_{t}^{1}|^{2} - \frac{\beta \cdot e^{-\frac{t}{\epsilon}}}{2} |\hat{u}_{t}^{2}|^{2}\bigg|^{2}\leqslant \frac{\beta^2}{4} \bigg|\hat{u}_{t}^{1} - \hat{u}_{t}^{2}\bigg|^{2} \bigg(\frac{3}{2}|\hat{u}_{t}^{1}|^{2} +\frac{3}{2} | \hat{u}_{t}^{2}|^{2}\bigg),\\
|g_{energy,2}|&=\bigg|\frac{\beta \cdot e^{-\frac{t}{\epsilon}}}{2\epsilon} |\nabla \hat{u}^{1}|^{2} - \frac{\beta \cdot e^{-\frac{t}{\epsilon}}}{2\epsilon} |\nabla \hat{u}_{t}^{2}|^{2}\bigg|^{2}\leqslant \frac{\beta^2}{4\epsilon^{2}} \bigg|\nabla \hat{u}^{1} - \nabla \hat{u}^{2}\bigg|^{2} \bigg(\frac{3}{2}|\nabla \hat{u}^{1}|^{2} +\frac{3}{2} |\nabla \hat{u}^{2}|^{2}\bigg),\\
|g_{energy,3}|&=\bigg|\frac{\beta\cdot e^{-\frac{t}{\epsilon}}}{\epsilon} fu^{1} - \frac{\beta\cdot e^{-\frac{t}{\epsilon}}}{\epsilon} fu^{2}  \bigg|^{2}\leqslant \frac{\beta^2}{\epsilon^{2}} \cdot f\cdot \bigg|\hat{u}^{1} - \hat{u}^{2}\bigg|^{2} .
\end{align}
Thanks to Sobolev Multiplication theorem Theorem~\ref{Thm.A5}, when $q\geqslant \frac{d}{2} +1$, we can obtain for any $t$,
\begin{align}
||g_{energy,1}(\cdot,t)||_{L^{2}_{x}(\mathbb{R}^{d})}\leqslant \frac{3\beta}{4}||\hat{u}_{t}^{1}(\cdot,t) - \hat{u}_{t}^{2}(\cdot,t)||_{H^{q}_{x}(\mathbb{R}^{d})}(||\hat{u}_{t}^{1}(\cdot,t)||_{H^{q}_{x}(\mathbb{R}^{d})} +||\hat{u}_{t}^{2}(\cdot,t)||_{H^{q}_{x}(\mathbb{R}^{d})}),\\
||g_{energy,2}(\cdot,t)||_{L^{2}_{x}(\mathbb{R}^{d})}\leqslant \frac{3\beta}{4\epsilon}||\hat{u}^{1}(\cdot,t) - \hat{u}^{2}(\cdot,t)||_{H^{q}_{x}(\mathbb{R}^{d})}(||\hat{u}^{1}(\cdot,t)||_{H^{q}_{x}(\mathbb{R}^{d})} +||\hat{u}^{2}(\cdot,t)||_{H^{q}_{x}(\mathbb{R}^{d})}).
\end{align}
Applying uniform control of Sobolev norm in time $t$ and orthogonality property of local basis $\phi_{\xi,\tau}(x,t)$, we have
\begin{align}
||g_{energy,1}||_{L^{2}_{t}(\mathbb{R};L^{2}_{x}(\mathbb{R}^{d}))}^{2}&\leqslant \frac{9\cdot R^{2}\cdot\beta^{2}}{16}||\hat{u}^{1} - \hat{u}^{2}||_{H^{1}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d}))}^{2}\\
&\leqslant \frac{9\cdot R^{2}\cdot\beta^{2}}{16}J^{2+4dq} \sum_{1\leqslant |\xi|_{\infty},\tau\leqslant J} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2}|^{2},
\end{align}
\begin{align}
||g_{energy,2}||_{L^{2}_{t}(\mathbb{R};L^{2}_{x}(\mathbb{R}^{d}))}^{2}&\leqslant \frac{9\cdot R^{2}\cdot \beta^{2}}{16\epsilon^{2}}||\hat{u}^{1} - \hat{u}^{2}||_{L^{2}_{t}(\mathbb{R};H^{q}_{x}(\mathbb{R}^{d}))}^{2}\\
&\leqslant \frac{9\cdot R^{2}\cdot \beta^{2}}{16\epsilon^{2}}J^{4dq} \sum_{1\leqslant |\xi|_{\infty},\tau\leqslant J} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2}|^{2}\\,
\end{align}
\begin{align}
||g_{energy,3}||_{L^{2}_{t}(\mathbb{R};L^{2}_{x}(\mathbb{R}^{d}))}^{2}&\leqslant \frac{\beta^{2}}{\epsilon^{2}}\cdot F^{2}  ||\hat{u}^{1} - \hat{u}^{2}||_{L^{2}_{t}(\mathbb{R};L^{2}_{x}(\mathbb{R}^{d}))}^{2}\\
&\leqslant \frac{\beta^{2}}{\epsilon^{2}}\cdot F^{2}J^{2d+4} \sum_{1\leqslant |\xi|_{\infty},\tau\leqslant J} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2}|^{2}.
\end{align}
It follows as before
\begin{align}
\log N(\mathcal{G}_{energy,1}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1})  &\lesssim J^{d+2}\bigg[\log{\frac{3R\cdot\beta}{4\epsilon_{1}}} + (2+dq)\log{J}\bigg],  \\
\log N(\mathcal{G}_{energy,2}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) &\lesssim J^{d+2}\bigg[\log{\frac{3R\cdot\beta}{4\epsilon\cdot \epsilon_{1}}} +dq\log{J}\bigg] ,\\
\log N(\mathcal{G}_{energy,3}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) &\lesssim J^{d+1}\bigg[\log{\frac{F\cdot \beta}{\epsilon\cdot\epsilon_{1}}} + (d+2)\log{J}\bigg].
\end{align}
we then bound $\mathcal{G}_{correction}$
\begin{align}
|g_{correction, 1}|&=\bigg| e^{-\frac{T}{\epsilon}} u_{t}^{*}(x,T) \hat{u}^{1}(x,T) -e^{-\frac{T}{\epsilon}} u_{t}^{*}(x,T) \hat{u}^{2}(x,T) \bigg|^{2}\\
&\leqslant  \bigg|\hat{u}_{t}^{1}(x,T) - \hat{u}_{t}^{2}(x,T)\bigg|^{2}\cdot \bigg|u^{*}_{t}(x,T)\bigg|^{2},\\
|g_{correction, 2}|&=\bigg|e^{-\frac{t}{\epsilon}}u^{*}_{tt}\hat{u}^{1} - e^{-\frac{t}{\epsilon}}u^{*}_{tt}\hat{u}^{2}\bigg|^{2}\leqslant e^{-\frac{2t}{\epsilon}} \bigg|\hat{u}^{1} -   \hat{u}^{2}\bigg|^{2} \cdot \bigg|u_{tt}^{*}\bigg|^{2}.
\end{align}
Again, we apply the Sobolev multiplication theorem (cf. Theorem~\ref{thm:sobolev_multiplication}) and use upper bound on Sobolev norm uniformly in time $t$ to get
\begin{align}
||\,g_{correction,1}\,||_{L^{2}_{t}(0,T;L^{2}_{x}(\mathbb{R}^{d})}&\leqslant \beta\cdot T ||\,\hat{u}^{1}_{t}(\cdot,T) - \hat{u}^{2}_{t}(\cdot,T)\,||_{ H^{q}_{x}(\mathbb{R}^{d})}||\,u_{t}^{*}(\cdot,T)\,||_{ H^{q}_{x}(\mathbb{R}^{d})}\\
&\leqslant \beta\cdot R\cdot T||\,\hat{u}^{1}_{t}(\cdot,T) - \hat{u}^{2}_{t}(\cdot,T)\,||_{ H^{q}_{x}(\mathbb{R}^{d})},\\
||g_{correction, 2}||_{L^{2}_{t}(0,T;L^{2}_{x}(\mathbb{R}^{d})}&\leqslant   \beta\cdot ||\hat{u}^{1} -   \hat{u}^{2}||_{L^{2}_{t}(0,T;H^{q}_{x}(\mathbb{R}^{d}))} \cdot ||u_{tt}^{*}||_{L^{2}_{t}(0,T;H^{q}_{x}(\mathbb{R}^{d}))}\\
&\leqslant R||\hat{u}^{1} -   \hat{u}^{2}||_{L^{2}_{t}(0,T;H^{q}_{x}(\mathbb{R}^{d}))}.
\end{align}
Here we use property \ref{basis_property_2} of our local basis $\phi_{\tau}(t)$ to get $\sup_{t} \phi_{\tau}\leqslant C(T)$, where $C(T)$ is some constant depending on $T$
\begin{align}
||g_{correction, 1}||_{L^{2}_{t}(0,T;L^{2}_{x})}^{2} &\leqslant  R^{2} T^{2} C(T)^{2} \beta^{2}J^{2+2dq} \sum_{1\leqslant |\xi|_{\infty},\tau\leqslant J} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2}|^{2},\\
||g_{correction, 2}||_{L^{2}_{t}(0,T;L^{2}_{x})}^{2} &\leqslant R^{2} \beta^{2}J^{2dq} \sum_{1\leqslant |\xi|_{\infty},\tau\leqslant J} |a_{\xi,\tau}^{1} - a_{\xi,\tau}^{2}|^{2}.
\end{align}
It follows
\begin{align}\log N(\mathcal{G}_{correction,1}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) &\lesssim J^{d+2}\bigg[\log{\frac{R\cdot T\cdot C(T)\cdot \beta}{4\epsilon\cdot \epsilon_{1}}} + (2+dq)\log{J}\bigg], \\
\log N(\mathcal{G}_{correction,2}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1})  &\lesssim J^{d+2}\bigg[\log{\frac{R\cdot \beta}{4\epsilon_{1}}} + dq\log{J}\bigg].
\end{align}
Finally, we obtain the following covering numbers for $\mathcal{G}_{data}$, $\mathcal{G}_{energy}$, and $\mathcal{G}_{correction}$ respectively
\begin{align}
\log N(\mathcal{G}_{data}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) & \lesssim  J^{d+2}\bigg[\log{\frac{1}{\epsilon_{1}}} + (1+d) \log{J} \bigg], \\
\log N(\mathcal{G}_{energy}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) & \lesssim  C_{1}(F)J^{d+2}\bigg[\log{\frac{\beta}{\epsilon_{1}}} + (1+dq)\log{J}\bigg],  \\
\log N(\mathcal{G}_{correction}, ||\cdot||_{L^{2}_{t}(0,T;L^{2}_{x}(\Omega))},\epsilon_{1}) &\lesssim C_{2}(R,T) J^{d+2}\bigg[\log{\frac{\beta}{\epsilon\cdot \epsilon_{1}}} + (1+dq)\log{J}\bigg],
\end{align}
where $C_{1}$ is some constant depending on $F$ and $R$; $C_{2}$ is some constant depending on $R$ and $T$.

First, we define population risk and its empirical parts:
\begin{align}
\mathcal{E}_{data}&:= {\mathbb{E}}\bigg[u(x,t) - u^{*}(x,t) + \nabla (u(x,t) - u^{*}(x,t)) \\&\quad\quad\quad\quad\quad+  (u_{t}(x,t) - u^{*}_{t}(x,t))+ \nabla u_{t}(x,t) -  \nabla u^{*}_{t}(x,t))\bigg], \\
\mathcal{E}_{data,n}&:= \frac{1}{nm} \sum_{i=1,j=1}^{n,m} \bigg[u(x_{ij},t_{j}) - u^{*}(x_{ij},t_{j}) + \nabla (u(x_{ij},t_{j}) - u^{*}(x_{ij},t_{j}))\\
&\quad\quad\quad\quad\quad\quad+  (u_{t}(x_{ij},t_{ij})- u^{*}_{t}(x_{ij},t_{j}))+ \nabla( u_{t}(x_{ij},t_{j})-  u^{*}_{t}(x,t))\bigg],\\
\mathcal{E}_{energy}&:= {\mathbb{E}}\bigg[\dfrac{\beta\cdot e^{-\frac{t}{\epsilon}}}{2}\bigg( |u_{t}|^{2}(x,t) +  \frac{1}{2\epsilon} |\nabla u|^{2}(x,t)- f(x,t)u(x,t) \bigg) \bigg], \\
\mathcal{E}_{energy,n}&:= \frac{\beta}{nm} \sum_{i=1,j=1}^{n,m}\cdot\bigg[\dfrac{e^{-\frac{t}{\epsilon}}}{2} \bigg(|u_{t}|^{2}(x_{ij},t_{j}) +  \frac{1}{2\epsilon} |\nabla u|^{2}(x_{ij},t_{j})- f(x_{ij},t_{j})u(x_{ij},t_{j}) \bigg) \bigg],\\
\mathcal{E}_{correction}&:= \beta\cdot{\mathbb{E}} \bigg[e^{-\frac{T}{\epsilon}}u^{*}_{t}(x,t_{m})u(x,t_{m})+  e^{-\frac{t}{\epsilon}}u^{*}_{tt}(x,t)u(x,t) \bigg],\\
\mathcal{E}_{correction,n}&:= \frac{\beta}{nm} \sum_{i=1,j=1}^{n,m} \bigg[e^{-\frac{T}{\epsilon}}u^{*}_{t}(x_{ij},t_{m})u(x_{ij},t_{m})+  e^{-\frac{t}{\epsilon}}u^{*}_{tt}(x_{ij},t_{j})u(x_{ij},t_{j}) \bigg].
\end{align}
It is essential to prove Lemma~\ref{lemma_E.5} and Lemma~\ref{lemma_E.6} before proving Theorem \ref{thm_3.4}.


With $L^{2}$-covering numbers at our hand, we can directly apply Dudley theorem to bound Rademacher complexities. Before applying Lemma \ref{lemma_F.8}, we need to find $\sup_{f\in \mathcal{F}} \mathbb{E}(f^{2})$. For $\mathcal{G}_{data}$, we have
\begin{equation}
\mathbb{E}[g_{data,1}^{2}]\lesssim \rho.
\end{equation}
For $\mathcal{G}_{energy}$, since $||f||_{L^{\infty}} \leqslant F$ and when $q\geqslant \frac{d}{2}+1$, we can apply embedding Theorem \ref{lemma_F.8} to spatial variable and obtain $H^{q}(\mathbb{R}^{d}) \subset W^{1,4}(\mathbb{R}^{d})$. Furthermore, when $p\geqslant2$, we have $u_{t}(t,\cdot) \in L^{4}([0,T])$ by standard Sobolev embedding theorem as well, and it follows that
\begin{align}
\mathbb{E}[g_{energy}^{2}]&\lesssim \int_{0}^{T} \int_{\mathbb{R}^{d}} (1+\frac{e^{\frac{-2t}{\epsilon}}}{4} )|u_{t}^{4}| + (1+\frac{1}{4\epsilon^{2}} )|\nabla u|^{4} + (1+\frac{e^{\frac{-2t}{\epsilon}}}{\epsilon^{2}}) f^{4} + (1+\frac{e^{\frac{-2t}{\epsilon}}}{\epsilon^{2}})u^{4}dxdt \\
&\lesssim \frac{5}{4}||u_{t}||_{L^{4}_{t}(0,T;L^{4}_{x}(\mathbb{R}^{d}))}^{4} +  (1+\frac{5}{4\epsilon^{2}})||u||_{L^{4}_{t}(0,T;W^{1,4}_{x}(\mathbb{R}^{d}))}^{4} + (1+\frac{1}{\epsilon^{2}})F^{4}\\
&\lesssim (1+\frac{5}{4\epsilon^{2}})(R^{4} + F^{4}).
\end{align}
For $\mathcal{G}_{correction}^{2}$, it follows that
\begin{align}
\mathbb{E}[\mathcal{G}_{correction}^{2}]&\leqslant \int_{0}^{T}\int_{\Omega} \frac{3}{4}|u_{tt}|^4 +\frac{3}{2} |u|^{4} dxdt + T\int_{\Omega} u_{t}^{4}(x,T) dx \\
&\lesssim \frac{3}{4}||u_{tt}||^{4}_{L^{4}_{t}(0,T;L^{4}_{x}(\mathbb{R}^{d}))} + \frac{3}{2}||u||^{4}_{L^{4}_{t}(0,T;L^{4}_{x}(\mathbb{R}^{d}))} + T||u_{t}(\cdot,T)||^{4}_{L^{4}_{x}(\mathbb{R}^{d})}\\
&\lesssim \frac{3}{2}R^{4} + T \max_{t\in[0,T]} ||u_{t}(\cdot,t)||_{L^{4}_{x}(\mathbb{R}^{d})}^{4} = \max\{\frac{3}{2},T\} (R^{4}+M^{4}(T)).
\end{align}
Finally, we can calculate with $C_{1}(R,F):={(1+\frac{5}{4\epsilon^{2}})(R^{4} + F^{4})} $ and $C_{2}(R,F) = (1+\frac{5}{4\epsilon^{2}})(R^{4} + F^{4})$, 
\begin{equation}
\mathcal{R}_n(\mathcal{G}_{data}) \le\inf_{0 \le \delta}\left(
4\delta + \frac{12}{\sqrt{nm}} \int_{\delta}^{R^{2}}\sqrt{J^{d+1}\bigg[\log{\frac{1}{\epsilon_{1}}} + (2+d) \log{J} \bigg]}\,d\varepsilon_{1}\right),
\end{equation}
\begin{equation}
\mathcal{R}_n(\mathcal{G}_{energy}) \le\inf_{0 \le \delta}\left(
4\delta + \frac{12}{\sqrt{nm}} \int_{\delta}^{C_{1}(R,F)}\sqrt{J^{d+1}\bigg[\log{\frac{\beta}{\epsilon\cdot\epsilon_{1}}} + (2+dq)\log{J} \bigg]}\,d\varepsilon_{1}\right),
\end{equation}
\begin{equation}
\mathcal{R}_n(\mathcal{G}_{correction}) \le\inf_{0 \le \delta}\left(
4\delta+ \frac{12}{\sqrt{nm}} \int_{\delta}^{C_{2}(R,F)}\sqrt{J^{d+1}\bigg[\log{\frac{\beta}{\epsilon\cdot\epsilon_{1}}} + (2+dq)\log{J} \bigg]}\,d\varepsilon_{1}\right).
\end{equation}
It follows that
\begin{align}
\mathcal{R}_{n}(\mathcal{G}_{data})&\lesssim  \sqrt{\frac{\rho}{nm}} J^{\frac{d+1}{2}}  \bigg[\sqrt{\log(\frac{1}{\rho}+1)} + \sqrt{(2+d)\log{J}}\bigg] \\
&\lesssim C_{3}(R) \sqrt{\frac{\rho}{nm}} J^{\frac{d+1}{2}} \sqrt{\log J \log (1+\frac{1}{\rho})},\\ 
\mathcal{R}_{n}(\mathcal{G}_{data})&\lesssim \sqrt{\frac{\beta}{nm}} J^{\frac{d+2}{2}} \sqrt{(1+\frac{5}{4})(R^{4}+F^{4})}\bigg[\sqrt{\log(\frac{1}{{(1+\frac{5}{4})(R^{4}+F^{4})\epsilon}}+1)}\\
&\quad+ \sqrt{(2+dq)\log{J}}\bigg]\\
&\lesssim C_{4}(\epsilon,d,q,R,F)\sqrt{\frac{\beta}{nm}} J^{\frac{d+2}{2}}\sqrt{\log{J}},  \\
\mathcal{R}_{n}(\mathcal{G}_{data})&\lesssim\sqrt{\frac{\beta}{nm}} J^{\frac{d+1}{2}} \sqrt{\max\{\frac{3}{2},T\}(R^{4}+M^{4}(T))} \bigg[\sqrt{\log(\frac{1}{{\max\{\frac{3}{2},T\}(R^{4}+M^{4}(T))\epsilon} }+1)}\\
&\quad\quad+ \sqrt{(2+dq)\log{J}}\bigg]\\
&\lesssim C_{5}(\epsilon, d,q,R,T)\sqrt{\frac{\beta}{nm}} J^{\frac{d+2}{2}} \sqrt{\log{J}}.
\end{align}
We need to appropriately balance the radius of localization ball $\rho$ and regularizing parameter $\beta$. We pick $\rho \approx \frac{1}{nm}$ and $\beta \approx \frac{\log{nm}}{nm} \log J$, and then
\begin{equation}
\mathcal{R}_{n}(\mathcal{G}) \lesssim C(\epsilon, d,q, R,T, F) J^{\frac{d+2} {2}}\log{J}\frac{\log{nm}}{nm}. 
\end{equation}

\label{thm:bernstein_ineq}
Let $X_{i}$,...,$X_{N}$ be i.i.d random variables. Suppose that $\mathbb{E}X_{i} =0$, $|X_{i}|\leqslant M$ almost surely, and $\frac{1}{N}\sum_{i=1}^{n}Var(X_{i}) \leqslant \sigma^{2}$. For any $t\geqslant0$, 
\begin{equation}
\mathbb{P}\left( \frac{1}{n}\sum_{i=1}^{n} X_{i}\geqslant t \right)\leqslant \exp\left(-\frac{nt^{2}}{2\sigma^2 + \frac{2}{3} Mt}\right).
\end{equation}

\label{lemma_F.2}
Let $\Omega$ be the domain and $\mathcal{F}$ be a set of functions $f$ and $\mathcal{P}_{\Omega}$ is probability measure from which $X$ is sampled. Then 
\begin{equation}
\mathbb{E}\, \underset{f\in \mathcal{F}}{\sup}\,\bigg|\frac{1}{n} \sum_{i=1}^{n} f(X_{i}) - \mathbb{E} f(X_i) \bigg| \leqslant 2 \mathcal{R}_{n,\mathcal{F}}.
\end{equation}

\label{theorem_A.3}
Let $\mathcal{F}$ be a function class such that $\sup_{f \in \mathcal{F}} \|f\|_{L_2(P_{n})} \le M $.
Then the Rademacher complexity $\mathcal{R}_n(\mathcal{F})$ satisfies
\begin{equation}
\mathcal{R}_n(\mathcal{F}) \le\inf_{0 \le \delta}\left\{
4\delta + \frac{12}{\sqrt{n}} \int_{\delta}^{\sup_{f\in\mathcal{F}}\mathbb{E}(f^{2})}\sqrt{\log N\!\left(\varepsilon,\,\mathcal{F},\,\|\cdot\|_{L^{2}(P_{n})}\right)}\,d\varepsilon\right\},
\end{equation}
where $N(\varepsilon,\mathcal{F},\|\cdot\|_{\infty})$ denotes the
$\varepsilon$-covering number of $\mathcal{F}$ with respect to the
$L^{\infty}$-norm.

Let $\mathcal{F}$ be a class of measurable functions such that 
$\mathbb{E}[f^2]<\sigma^2$ and $||f||_{\infty}<L$ for all $f\in \mathcal{F}$. Then, 
\begin{equation}
\mathbb{E}\bigg[\underset{f\in \mathcal{F}}{\sup} |\sqrt{n}\bigl(\hat{P} - P\bigr)f | \bigg] 
\lesssim \mathcal{D}_{[\,\,]}(\sigma, \mathcal{F},L_{2}(P)) \bigg(\mathcal{D}_{[\,\,]}(\sigma, \mathcal{F},L_{2}(P)) + \frac{\mathcal{D}_{[\,\,]}(\sigma, \mathcal{F},L_{2}(P))}{\sigma^2\sqrt{n}} L \bigg).
\end{equation}
\label{Bernstein Chaining}
\begin{proof}
Apply \citet[Lemma~3.4.2]{vanderVaart1996}
to $\mathcal F/L$ and rescale.
\end{proof}

Let $\mathcal{F}$ be a class of measurable functions such that $\mathbb{E}[f^2]<\sigma^2$ and $||f||_{\infty}<L$ for all $f\in \mathcal{F}$. Then
\begin{equation}
\mathbb{P}\bigg( \underset{f\in\mathcal{F}}{\sup} \sqrt{n} |(\hat{P}-P)f|\geqslant 2\mathbb{E}[\underset{f\in\mathcal{F}}{\sup} |(\hat{P} - P)f| + \sigma\sqrt{2s} + \frac{L}{\sqrt{n}}s  \bigg)\leqslant e^{-s}.
\end{equation} \label{Talagrand Inequality}

(Covering numbers for $L_2$ balls) Let $p\in \mathbb{N}$ and $B_{2}(r)$ be the $L_{2}$ balls of $\mathbb{R}^{d}$ with radius $r$ such that $\epsilon \leqslant r$. Then 
\begin{equation}N(B_{2}(r),||\cdot||_{2},\epsilon) \leqslant \left(\frac{3r}{\epsilon}\right)^{d}.
\end{equation}
\label{lemma_F.6}

\label{thm:sobolev_multiplication}
Let $\Omega \subseteq \mathbb{R}^d$ be a Lipschitz domain, and let $s > \frac{d}{p}$ with $1 \leqslant p \leqslant \infty$. For any $u, v \in W^{s,p}(\Omega)$,  there exists a constant $C = C(n, s, p, \Omega)$ such that:
\label{Thm.A5}
\begin{equation}
    \|uv\|_{W^{s,p}(\Omega)} \leqslant C \|u\|_{W^{s,p}(\Omega)} \|v\|_{W^{s,p}(\Omega)}.
\end{equation}

\label{lem:weighted-poincare}
Let $\Omega$ be bounded Lipschitz domain and $w(x)$ be non-negative weight on $\Omega$. There exist constant $C := C(d,\Omega, w) > 0$ such that for any $f\in H^{1}(\Omega)$, we have
\begin{equation}
\|(f- f_{w,\Omega})w(\cdot)\|_{L^{2}(\Omega)} \leqslant C \|w(\cdot)\nabla f \|_{L^{2}(\Omega)},
\end{equation}
where $f_{w,\Omega}:= \frac{\int_{\Omega}w(x)f(x)dx}{\int_{\Omega}w(x)dx}$.

To prove (F.1), we note 
\begin{align}
||P_{J}f||_{L^{2}_{t}(\mathbb{R};L^{2}_{x}(\mathbb{R}^{d}))}^{2}  &\leqslant ||f||_{H^{1}_{t}(\mathbb{R};H^{1}_{x} (\mathbb{R}^{d}))}^{2}\\
&\leqslant C(\Omega,T) ||f||_{H^{1}_{t}([0,T];H^{1}_{x} (\Omega))}^{2} \hspace{0.5cm} - \text{ Lemma~\ref{space_time_extension} }.
\end{align}
To prove (70), we only need to rewrite 
\begin{equation}
P_{J}f = \sum_{1\leqslant \tau,|\xi|\leqslant J} |\xi|^{p} \tau^{q} \frac{1}{|\xi|^{p}\tau^{q}} a_{\xi,\tau} \phi_{\xi,\tau}(x,t).
\end{equation}
From Morrey's embedding in case of $q>\frac{d}{2}$ and the Sobolev norm of $f$ is bounded by $R$ and the extension Theorem \ref{Sobolev_extension_theorem},
\begin{align}
||P_{J}f(\cdot,t)||_{\infty} \leqslant C(\Omega)||P_{J}f(\cdot,t)||_{H^{q}(\Omega)}\leqslant C(\Omega)R,\quad \forall t\in[0,T].
\end{align}
Otherwise, if $q\leqslant \frac{d}{2}$, we note there are finitely many coefficients $a_{\xi,\tau}$ and each $\phi_{\xi,\tau}(x,t)$ has local compact support
\begin{equation}
P_{J}f = \sum_{1\leqslant \tau\leqslant J^{2},1\leqslant |\xi|\leqslant J}  a_{\xi,\tau} \phi_{\xi,\tau}(x,t) \leqslant ||a_{\xi,\tau}||_{\infty}  \sum_{1\leqslant \tau\leqslant J^{2},1\leqslant |\xi|\leqslant J}  \phi_{\xi,\tau}(x,t) \leqslant C(\Omega, T) J^{d+2}.
\end{equation}

\label{lem:moments_of_wavelets}
Let $\phi_\tau(t)=2^{\ell/2}\varphi(2^\ell t-k_0)$ be an $L^2$-normalized
compactly supported wavelet at level $2^\ell\asymp J^2$, let
$T_1,\dots,T_n$ be i.i.d.\ uniform on $[0,T]$, and set
$Y_j:=\phi_\tau(T_j)^2$,
$B:=\frac1n\sum_{j=1}^n\big(Y_j-\mathbb{E} Y_1\big)$. Then
\begin{equation}\label{eq:moments}
\text{Var}(Y_1)\asymp J^2,\qquad
\mathbb{E}\big|Y_1-\mathbb{E} Y_1\big|^4\lesssim J^6,
\end{equation}
and there exist constants $c_1,c_2>0$ such that, whenever
$n\geqslant J^2$,
\begin{equation}\label{eq:anticonc}
\mathbb{P}\Big(|B|\geqslant c_1\sqrt{J^2/n}\Big)\;\geqslant\;c_2.
\end{equation}
